diffs.replacement:
{
  "name": "Конструктор строительной разметки",
  "description": "Инструмент для точного распределения элементов (точек или досок) между двумя окружностями с визуализацией и линейкой для разметки на объекте."
}

export type ElementType = 'point' | 'board';
export type DistanceMode = 'center-to-center' | 'edge-to-edge';
export type DistributionMode = 'by-gap' | 'by-count';
export type RulerMarkMode = 'center' | 'edge';

export interface AppConfig {
  diameter: number;
  distanceMode: DistanceMode;
  distanceValue: number;
  elementType: ElementType;
  boardWidth: number;
  distributionMode: DistributionMode;
  targetGap: number;
  elementCount: number;
  maxEndGap: number;
  rulerMarkMode: RulerMarkMode;
  showDimensions: boolean;
}

export interface CalculationResult {
  edgeToEdge: number;
  centerToCenter: number;
  actualGap: number;
  elementCount: number;
  firstElementOffset: number;
  warnings: string[];
  elementPositions: number[]; // relative to the inner edge of the first circle
}

import { AppConfig, CalculationResult } from '../types';

export const calculateLayout = (config: AppConfig): CalculationResult => {
  const {
    diameter,
    distanceMode,
    distanceValue,
    elementType,
    boardWidth,
    distributionMode,
    targetGap,
    elementCount: manualCount,
    maxEndGap
  } = config;

  // Internal values in mm to avoid precision loss
  const D = diameter * 10;
  const V = distanceValue * 10;
  const W = elementType === 'point' ? 0 : boardWidth * 10;
  const M = maxEndGap * 10;

  let S: number; // edge to edge distance
  let L: number; // center to center distance

  if (distanceMode === 'center-to-center') {
    L = V;
    S = L - D;
  } else {
    S = V;
    L = S + D;
  }

  const warnings: string[] = [];
  if (S < 0) warnings.push('Расстояние между окружностями отрицательное');

  let N = manualCount;
  let G = 0;

  if (distributionMode === 'by-gap') {
    const desiredG = targetGap * 10;
    // (N * W) + (N + 1) * G = S
    // N(W + G) = S - G
    // N = (S - G) / (W + G)
    N = Math.floor((S - desiredG) / (W + desiredG));
    if (N < 0) N = 0;
  }

  // Final count of elements must be at least 0
  if (N < 0) N = 0;

  // Recalculate actual gap for uniform distribution
  // Total gaps = N + 1
  if (N >= 0) {
    const totalElementWidth = N * W;
    const availableForGaps = S - totalElementWidth;
    G = availableForGaps / (N + 1);
  }

  if (G < 0) warnings.push('Элементы не помещаются в заданное пространство');
  if (G > M) warnings.push('Нарушен максимальный отступ от окружности');

  // Positions of elements relative to inner edge of first circle
  // We store the center point for points, and the left edge for boards
  const elementPositions: number[] = [];
  for (let i = 1; i <= N; i++) {
    // Offset = G * i + W * (i-1)
    const pos = G * i + W * (i - 1);
    elementPositions.push(pos);
  }

  return {
    edgeToEdge: S / 10,
    centerToCenter: L / 10,
    actualGap: G / 10,
    elementCount: N,
    firstElementOffset: G / 10,
    warnings,
    elementPositions: elementPositions.map(p => p / 10)
  };
};

export const formatCm = (mmValue: number): string => {
  return (Math.round(mmValue * 10) / 10).toFixed(1);
};

import React from 'react';
import { Info } from 'lucide-react';

interface InfoTooltipProps {
  text: string;
}

export const InfoTooltip: React.FC<InfoTooltipProps> = ({ text }) => {
  return (
    <div className="group relative inline-block ml-1 align-middle">
      <Info className="w-4 h-4 text-slate-400 cursor-help" />
      <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 hidden group-hover:block w-48 p-2 bg-slate-800 text-white text-xs rounded shadow-lg z-50">
        {text}
        <div className="absolute top-full left-1/2 -translate-x-1/2 border-8 border-transparent border-t-slate-800"></div>
      </div>
    </div>
  );
};

import React from 'react';
import { AppConfig, CalculationResult } from '../types';
import { formatCm } from '../utils/calculations';

interface MainDiagramProps {
  config: AppConfig;
  result: CalculationResult;
}

export const MainDiagram: React.FC<MainDiagramProps> = ({ config, result }) => {
  const { diameter, elementType, boardWidth, showDimensions } = config;
  const { edgeToEdge, elementPositions, actualGap } = result;

  const padding = 60;
  const circleRadius = diameter / 2;
  const canvasWidth = edgeToEdge + diameter * 2 + padding * 2;
  const canvasHeight = diameter + padding * 2;

  // Scale to fit screen
  const viewWidth = 1000;
  const scale = viewWidth / canvasWidth;
  const viewHeight = canvasHeight * scale;

  return (
    <div className="w-full bg-white rounded-xl shadow-sm border border-slate-200 p-6 overflow-x-auto">
      <h3 className="text-sm font-semibold text-slate-500 uppercase tracking-wider mb-4">Основная схема</h3>
      <div className="min-w-[600px]">
        <svg
          viewBox={`0 0 ${viewWidth} ${viewHeight}`}
          className="w-full h-auto"
        >
          {/* Main Axis */}
          <line
            x1={padding * scale}
            y1={viewHeight / 2}
            x2={(canvasWidth - padding) * scale}
            y2={viewHeight / 2}
            stroke="#e2e8f0"
            strokeWidth="1"
            strokeDasharray="5,5"
          />

          {/* First Circle */}
          <circle
            cx={(padding + circleRadius) * scale}
            cy={viewHeight / 2}
            r={circleRadius * scale}
            fill="#f1f5f9"
            stroke="#64748b"
            strokeWidth="2"
          />
          <circle
            cx={(padding + circleRadius) * scale}
            cy={viewHeight / 2}
            r="2"
            fill="#64748b"
          />

          {/* Second Circle */}
          <circle
            cx={(padding + circleRadius + diameter + edgeToEdge) * scale}
            cy={viewHeight / 2}
            r={circleRadius * scale}
            fill="#f1f5f9"
            stroke="#64748b"
            strokeWidth="2"
          />
          <circle
            cx={(padding + circleRadius + diameter + edgeToEdge) * scale}
            cy={viewHeight / 2}
            r="2"
            fill="#64748b"
          />

          {/* Connection Line */}
          <line
            x1={(padding + diameter) * scale}
            y1={viewHeight / 2}
            x2={(padding + diameter + edgeToEdge) * scale}
            y2={viewHeight / 2}
            stroke="#3b82f6"
            strokeWidth="2"
          />

          {/* Elements */}
          {elementPositions.map((pos, idx) => {
            const x = (padding + diameter + pos) * scale;
            if (elementType === 'point') {
              return (
                <g key={idx}>
                  <circle cx={x} cy={viewHeight / 2} r="4" fill="#ef4444" />
                  {showDimensions && (
                     <text x={x} y={viewHeight / 2 - 10} textAnchor="middle" className="text-[10px] fill-red-600 font-medium">{idx + 1}</text>
                  )}
                </g>
              );
            } else {
              const width = boardWidth * scale;
              return (
                <rect
                  key={idx}
                  x={x}
                  y={viewHeight / 2 - (diameter / 4) * scale}
                  width={width}
                  height={(diameter / 2) * scale}
                  fill="#ef4444"
                  rx="2"
                />
              );
            }
          })}

          {/* Dimensions */}
          {showDimensions && (
            <g className="text-[12px] fill-slate-500 font-medium">
              {/* Edge to edge */}
              <path
                d={`M ${(padding + diameter) * scale} ${viewHeight - 20} L ${(padding + diameter + edgeToEdge) * scale} ${viewHeight - 20}`}
                stroke="#cbd5e1"
                markerStart="url(#arrowhead)"
                markerEnd="url(#arrowhead)"
              />
              <text x={(padding + diameter + edgeToEdge / 2) * scale} y={viewHeight - 5} textAnchor="middle">
                {formatCm(edgeToEdge)} см
              </text>

              {/* First Gap */}
              {elementPositions.length > 0 && (
                <g>
                   <path
                    d={`M ${(padding + diameter) * scale} ${viewHeight / 2 - 30} L ${(padding + diameter + actualGap) * scale} ${viewHeight / 2 - 30}`}
                    stroke="#94a3b8"
                    markerStart="url(#arrowhead)"
                    markerEnd="url(#arrowhead)"
                  />
                  <text x={(padding + diameter + actualGap / 2) * scale} y={viewHeight / 2 - 40} textAnchor="middle" className="fill-blue-600 text-[10px]">
                    {formatCm(actualGap)}
                  </text>
                </g>
              )}

              {/* Interval Gaps */}
              {elementPositions.length > 1 && (
                 <g>
                  <path
                    d={`M ${(padding + diameter + elementPositions[0] + (elementType === 'board' ? boardWidth : 0)) * scale} ${viewHeight / 2 - 30} L ${(padding + diameter + elementPositions[1]) * scale} ${viewHeight / 2 - 30}`}
                    stroke="#94a3b8"
                    markerStart="url(#arrowhead)"
                    markerEnd="url(#arrowhead)"
                  />
                  <text x={(padding + diameter + elementPositions[0] + (elementType === 'board' ? boardWidth : 0) + actualGap / 2) * scale} y={viewHeight / 2 - 40} textAnchor="middle" className="fill-blue-600 text-[10px]">
                    {formatCm(actualGap)}
                  </text>
                 </g>
              )}
            </g>
          )}

          <defs>
            <marker id="arrowhead" markerWidth="10" markerHeight="7" refX="0" refY="3.5" orient="auto">
              <polygon points="0 0, 10 3.5, 0 7" fill="#cbd5e1" />
            </marker>
          </defs>
        </svg>
      </div>
    </div>
  );
};

import React from 'react';
import { AppConfig, CalculationResult } from '../types';
import { formatCm } from '../utils/calculations';

interface ConstructionRulerProps {
  config: AppConfig;
  result: CalculationResult;
}

export const ConstructionRuler: React.FC<ConstructionRulerProps> = ({ config, result }) => {
  const { elementType, boardWidth, rulerMarkMode } = config;
  const { elementPositions } = result;

  return (
    <div className="w-full bg-white rounded-xl shadow-sm border border-slate-200 p-6 overflow-hidden">
      <div className="flex items-center justify-between mb-6">
        <h3 className="text-sm font-semibold text-slate-500 uppercase tracking-wider">Линейка для разметки</h3>
        <div className="flex gap-2 text-xs">
          <span className="flex items-center gap-1"><div className="w-3 h-3 bg-blue-500 rounded-full"></div> Начало зоны</span>
          <span className="flex items-center gap-1"><div className="w-3 h-3 bg-red-500 rounded-full"></div> Отметки</span>
        </div>
      </div>

      <div className="relative overflow-x-auto pb-8">
        <div className="min-w-full inline-block relative border-b-2 border-slate-300 pt-12 h-32">
          {/* Zero mark */}
          <div className="absolute left-0 bottom-0 translate-x-1/2 flex flex-col items-center">
             <div className="w-0.5 h-6 bg-blue-600"></div>
             <span className="mt-2 text-xs font-bold text-blue-700">0</span>
             <span className="text-[10px] text-slate-400 mt-0.5">Край окр.</span>
          </div>

          {/* Element marks */}
          {elementPositions.map((pos, idx) => {
            // Adjust position based on whether we show center or edge
            let markPos = pos;
            let labelSuffix = '';

            if (elementType === 'board') {
              if (rulerMarkMode === 'center') {
                markPos = pos + boardWidth / 2;
                labelSuffix = ' (центр)';
              } else {
                labelSuffix = ' (край)';
              }
            }

            return (
              <div 
                key={idx} 
                className="absolute bottom-0 flex flex-col items-center group transition-all"
                style={{ left: `${(markPos / (elementPositions[elementPositions.length-1] + 10)) * 90}%`, transform: 'translateX(-50%)' }}
              >
                <div className="w-0.5 h-10 bg-red-500"></div>
                <div className="mt-2 flex flex-col items-center">
                  <span className="text-sm font-bold text-slate-900">{formatCm(markPos)}</span>
                  <span className="text-[10px] text-slate-500 whitespace-nowrap">{idx + 1}-й эл.{labelSuffix}</span>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      <div className="mt-8 grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-3">
        {elementPositions.map((pos, idx) => {
          const markPos = elementType === 'board' && rulerMarkMode === 'center' ? pos + boardWidth / 2 : pos;
          return (
            <div key={idx} className="flex justify-between items-center p-3 bg-slate-50 rounded-lg border border-slate-100">
              <span className="text-xs font-medium text-slate-500">{idx + 1}-й элемент:</span>
              <span className="text-lg font-bold text-slate-800">{formatCm(markPos)} <span className="text-sm font-normal text-slate-400">см</span></span>
            </div>
          );
        })}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { 
  Circle, 
  ArrowLeftRight, 
  Box, 
  LayoutGrid, 
  AlertTriangle, 
  Settings2, 
  Printer, 
  Share2, 
  Plus, 
  Minus,
  Maximize2
} from 'lucide-react';
import { AppConfig, DistanceMode, ElementType, DistributionMode, RulerMarkMode } from './types';
import { calculateLayout } from './utils/calculations';
import { MainDiagram } from './components/MainDiagram';
import { ConstructionRuler } from './components/ConstructionRuler';
import { InfoTooltip } from './components/InfoTooltip';

const INITIAL_STATE: AppConfig = {
  diameter: 150,
  distanceMode: 'center-to-center',
  distanceValue: 400,
  elementType: 'point',
  boardWidth: 10,
  distributionMode: 'by-gap',
  targetGap: 50,
  elementCount: 5,
  maxEndGap: 60,
  rulerMarkMode: 'edge',
  showDimensions: true,
};

const App: React.FC = () => {
  const [config, setConfig] = useState<AppConfig>(() => {
    const hash = window.location.hash.substring(1);
    if (hash) {
      try {
        return { ...INITIAL_STATE, ...JSON.parse(decodeURIComponent(hash)) };
      } catch (e) {
        return INITIAL_STATE;
      }
    }
    return INITIAL_STATE;
  });

  const [result, setResult] = useState(calculateLayout(config));

  useEffect(() => {
    const newResult = calculateLayout(config);
    setResult(newResult);
    window.location.hash = encodeURIComponent(JSON.stringify(config));
  }, [config]);

  const updateConfig = (updates: Partial<AppConfig>) => {
    setConfig(prev => ({ ...prev, ...updates }));
  };

  const handlePrint = () => {
    window.print();
  };

  const handleShare = () => {
    navigator.clipboard.writeText(window.location.href);
    alert('Ссылка скопирована в буфер обмена!');
  };

  return (
    <div className="min-h-screen pb-20 sm:pb-8">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-40 no-print">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-blue-600 p-2 rounded-lg">
              <LayoutGrid className="text-white w-5 h-5" />
            </div>
            <h1 className="text-lg font-bold text-slate-800 hidden sm:block">Разметка Элементов</h1>
          </div>
          <div className="flex items-center gap-2">
            <button 
              onClick={handleShare}
              className="p-2 text-slate-500 hover:bg-slate-100 rounded-lg transition-colors"
              title="Поделиться"
            >
              <Share2 className="w-5 h-5" />
            </button>
            <button 
              onClick={handlePrint}
              className="flex items-center gap-2 bg-slate-100 hover:bg-slate-200 text-slate-700 px-4 py-2 rounded-lg font-medium transition-colors"
            >
              <Printer className="w-4 h-4" />
              <span className="hidden sm:inline">Печать</span>
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

          {/* Controls Panel */}
          <div className="lg:col-span-4 space-y-6 no-print">

            {/* Platform Block */}
            <section className="bg-white p-5 rounded-2xl shadow-sm border border-slate-200">
              <div className="flex items-center gap-2 mb-4">
                <Circle className="w-5 h-5 text-blue-500" />
                <h2 className="font-bold text-slate-800">Платформа</h2>
                <InfoTooltip text="Параметры опорных окружностей (оснований)" />
              </div>
              <div className="space-y-4">
                <div>
                  <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Диаметр окружности (см)</label>
                  <div className="grid grid-cols-3 gap-2">
                    {[120, 150, 180].map(d => (
                      <button
                        key={d}
                        onClick={() => updateConfig({ diameter: d })}
                        className={`py-2 px-3 rounded-lg border text-sm font-medium transition-all ${
                          config.diameter === d 
                            ? 'bg-blue-50 border-blue-200 text-blue-600 shadow-sm' 
                            : 'bg-white border-slate-200 text-slate-600 hover:border-slate-300'
                        }`}
                      >
                        {d} см
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            </section>

            {/* Distance Block */}
            <section className="bg-white p-5 rounded-2xl shadow-sm border border-slate-200">
              <div className="flex items-center gap-2 mb-4">
                <ArrowLeftRight className="w-5 h-5 text-blue-500" />
                <h2 className="font-bold text-slate-800">Расстояние</h2>
              </div>
              <div className="space-y-4">
                <div className="flex p-1 bg-slate-100 rounded-xl">
                  <button
                    onClick={() => updateConfig({ distanceMode: 'center-to-center' })}
                    className={`flex-1 py-1.5 px-2 rounded-lg text-xs font-medium transition-all ${
                      config.distanceMode === 'center-to-center' ? 'bg-white shadow text-blue-600' : 'text-slate-500'
                    }`}
                  >
                    По осям
                  </button>
                  <button
                    onClick={() => updateConfig({ distanceMode: 'edge-to-edge' })}
                    className={`flex-1 py-1.5 px-2 rounded-lg text-xs font-medium transition-all ${
                      config.distanceMode === 'edge-to-edge' ? 'bg-white shadow text-blue-600' : 'text-slate-500'
                    }`}
                  >
                    От края до края
                  </button>
                </div>
                <div>
                  <label className="text-xs font-semibold text-slate-500 mb-1.5 block">
                    {config.distanceMode === 'center-to-center' ? 'Между центрами (см)' : 'Между краями (см)'}
                  </label>
                  <input
                    type="number"
                    value={config.distanceValue}
                    onChange={(e) => updateConfig({ distanceValue: Number(e.target.value) })}
                    className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all"
                  />
                </div>
              </div>
            </section>

            {/* Element Type */}
            <section className="bg-white p-5 rounded-2xl shadow-sm border border-slate-200">
              <div className="flex items-center gap-2 mb-4">
                <Box className="w-5 h-5 text-blue-500" />
                <h2 className="font-bold text-slate-800">Тип элемента</h2>
              </div>
              <div className="space-y-4">
                <div className="flex p-1 bg-slate-100 rounded-xl">
                  <button
                    onClick={() => updateConfig({ elementType: 'point' })}
                    className={`flex-1 py-1.5 px-2 rounded-lg text-xs font-medium transition-all ${
                      config.elementType === 'point' ? 'bg-white shadow text-blue-600' : 'text-slate-500'
                    }`}
                  >
                    Точка
                  </button>
                  <button
                    onClick={() => updateConfig({ elementType: 'board' })}
                    className={`flex-1 py-1.5 px-2 rounded-lg text-xs font-medium transition-all ${
                      config.elementType === 'board' ? 'bg-white shadow text-blue-600' : 'text-slate-500'
                    }`}
                  >
                    Доска
                  </button>
                </div>
                {config.elementType === 'board' && (
                  <div>
                    <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Ширина доски (см)</label>
                    <input
                      type="number"
                      value={config.boardWidth}
                      onChange={(e) => updateConfig({ boardWidth: Number(e.target.value) })}
                      className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all"
                    />
                  </div>
                )}
              </div>
            </section>

            {/* Distribution */}
            <section className="bg-white p-5 rounded-2xl shadow-sm border border-slate-200">
              <div className="flex items-center gap-2 mb-4">
                <LayoutGrid className="w-5 h-5 text-blue-500" />
                <h2 className="font-bold text-slate-800">Распределение</h2>
              </div>
              <div className="space-y-4">
                <div className="flex p-1 bg-slate-100 rounded-xl">
                  <button
                    onClick={() => updateConfig({ distributionMode: 'by-gap' })}
                    className={`flex-1 py-1.5 px-2 rounded-lg text-xs font-medium transition-all ${
                      config.distributionMode === 'by-gap' ? 'bg-white shadow text-blue-600' : 'text-slate-500'
                    }`}
                  >
                    По отступу
                  </button>
                  <button
                    onClick={() => updateConfig({ distributionMode: 'by-count' })}
                    className={`flex-1 py-1.5 px-2 rounded-lg text-xs font-medium transition-all ${
                      config.distributionMode === 'by-count' ? 'bg-white shadow text-blue-600' : 'text-slate-500'
                    }`}
                  >
                    По количеству
                  </button>
                </div>

                {config.distributionMode === 'by-gap' ? (
                  <div>
                    <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Желаемый отступ (см)</label>
                    <input
                      type="number"
                      value={config.targetGap}
                      onChange={(e) => updateConfig({ targetGap: Number(e.target.value) })}
                      className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all"
                    />
                  </div>
                ) : (
                  <div>
                    <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Количество элементов</label>
                    <div className="flex gap-2">
                      <button 
                        onClick={() => updateConfig({ elementCount: Math.max(0, config.elementCount - 1) })}
                        className="p-2 bg-slate-100 rounded-lg text-slate-600 hover:bg-slate-200"
                      >
                        <Minus className="w-4 h-4" />
                      </button>
                      <input
                        type="number"
                        value={config.elementCount}
                        onChange={(e) => updateConfig({ elementCount: Math.max(0, Number(e.target.value)) })}
                        className="flex-1 bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm text-center font-bold"
                      />
                      <button 
                        onClick={() => updateConfig({ elementCount: config.elementCount + 1 })}
                        className="p-2 bg-slate-100 rounded-lg text-slate-600 hover:bg-slate-200"
                      >
                        <Plus className="w-4 h-4" />
                      </button>
                    </div>
                  </div>
                )}
              </div>
            </section>

            {/* Constraints */}
            <section className="bg-white p-5 rounded-2xl shadow-sm border border-slate-200">
              <div className="flex items-center gap-2 mb-4">
                <Maximize2 className="w-5 h-5 text-blue-500" />
