import { AppConfig, CalculationResult } from '../types';

export const calculateLayout = (config: AppConfig): CalculationResult => {
  const {
    diameter,
    distanceMode,
    distanceValue,
    elementType,
    boardWidth,
    distributionMode,
    targetGap,
    elementCount: manualCount,
    maxEndGap
  } = config;

  // Values in mm
  const D = diameter;
  const V = distanceValue;
  const W = elementType === 'point' ? 0 : boardWidth;
  const M = maxEndGap;

  let S: number; // edge to edge distance
  let L: number; // center to center distance

  if (distanceMode === 'center-to-center') {
    L = V;
    S = L - D;
  } else {
    S = V;
    L = S + D;
  }

  const warnings: string[] = [];
  if (S < 0) warnings.push('Дистанция между платформами слишком мала (отрицательная)');

  let N = manualCount;

  if (distributionMode === 'by-gap') {
    const desiredG = targetGap;
    // We want to find the smallest N such that the resulting gap G <= desiredG
    // (N+1)G + NW = S  => G = (S - NW) / (N+1)
    // (S - NW) / (N+1) <= desiredG
    // S - NW <= desiredG * N + desiredG
    // S - desiredG <= N(desiredG + W)
    // N >= (S - desiredG) / (desiredG + W)
    if (desiredG + W > 0) {
      N = Math.ceil((S - desiredG) / (desiredG + W));
    } else {
      N = 0;
    }
    if (N < 0) N = 0;
  }

  // Recalculate actual gap for uniform distribution
  let actualG = 0;
  if (S > 0) {
    const totalElementWidth = N * W;
    const availableForGaps = S - totalElementWidth;
    actualG = availableForGaps / (N + 1);
  }

  if (actualG < 0) {
    warnings.push('Элементы не помещаются (увеличьте расстояние или уменьшите количество)');
  }

  // Show max offset warning
  if (actualG > M) {
    warnings.push('Нарушен максимальный отступ от края платформы');
  }

  const elementPositions: number[] = [];
  for (let i = 1; i <= N; i++) {
    const pos = actualG * i + W * (i - 1);
    elementPositions.push(pos);
  }

  return {
    edgeToEdge: S,
    centerToCenter: L,
    actualGap: actualG,
    elementCount: N,
    firstElementOffset: actualG,
    warnings,
    elementPositions
  };
};

