  rulerMarkMode: 'edge',
  showDimensions: true,
};

const App: React.FC = () => {
  const [config, setConfig] = useState<AppConfig>(() => {
    // 1. Try URL Hash
    try {
      const hash = window.location.hash.substring(1);
      if (hash) {
        return { ...INITIAL_STATE, ...JSON.parse(decodeURIComponent(hash)) };
      }
    } catch (e) {
      console.warn('Failed to read configuration from URL hash:', e);
    }

    // 2. Try LocalStorage
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        return { ...INITIAL_STATE, ...JSON.parse(saved) };
      }
    } catch (e) {
      console.warn('Failed to read configuration from localStorage:', e);
    }

    return INITIAL_STATE;
  });

  const [result, setResult] = useState(calculateLayout(config));

  useEffect(() => {
    const newResult = calculateLayout(config);
    setResult(newResult);

    // Persist to localStorage
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(config));
    } catch (e) {
      console.error('Failed to save to localStorage:', e);
    }

    // Sync to Hash for sharing
    try {
      const configString = JSON.stringify(config);
      const encodedConfig = encodeURIComponent(configString);
      if (window.location.hash !== `#${encodedConfig}`) {
        window.location.hash = encodedConfig;
      }
    } catch (e) {
      console.warn('URL hash synchronization is not available in this environment.');
    }
  }, [config]);

