import { AppConfig, CalculationResult } from '../types';

export const calculateLayout = (config: AppConfig): CalculationResult => {
  const {
    diameter,
    distanceMode,
    distanceValue,
    elementType,
    boardWidth,
    distributionMode,
    targetGap,
    elementCount: manualCount,
    maxEndGap
  } = config;

  // Values in mm
  const D = diameter;
  const V = distanceValue;
  const W = elementType === 'point' ? 0 : boardWidth;
  const M = maxEndGap;

  let S: number; // edge to edge distance
  let L: number; // center to center distance

  if (distanceMode === 'center-to-center') {
    L = V;
    S = L - D;
  } else {
    S = V;
    L = S + D;
  }

  const warnings: string[] = [];
  if (S < 0) warnings.push('Дистанция слишком мала (отрицательная)');

  let N = manualCount;

  if (distributionMode === 'by-gap') {
    // Hard constraint: the gap must not exceed maxEndGap.
    // If targetGap is larger than maxEndGap, we must use maxEndGap to find the minimum N.
    const effectiveDesiredG = Math.min(targetGap, M);

    if (effectiveDesiredG + W > 0) {
      // Find smallest N such that (S - NW) / (N + 1) <= effectiveDesiredG
      const calculatedN = Math.ceil((S - effectiveDesiredG) / (effectiveDesiredG + W));
      N = Math.max(0, calculatedN);
    } else {
      N = 0;
    }
  }

  // Recalculate actual gap for uniform distribution
  let actualG = 0;
  if (S > 0) {
    const totalElementWidth = N * W;
    const availableForGaps = S - totalElementWidth;
    actualG = availableForGaps / (N + 1);
  }

  if (actualG < 0) {
    warnings.push('Элементы не помещаются (увеличьте расстояние или уменьшите количество)');
  }

  // Strict check: if the resulting gap exceeds M, it's a violation.
  if (actualG > M + 0.1) { // 0.1 for float precision
    warnings.push('Нарушен максимальный отступ от края платформы (превышает ' + M + ' мм)');
  }

  const elementPositions: number[] = [];
  for (let i = 1; i <= N; i++) {
    const pos = actualG * i + W * (i - 1);
    elementPositions.push(pos);
  }

  return {
    edgeToEdge: S,
    centerToCenter: L,
    actualGap: actualG,
    elementCount: N,
    firstElementOffset: actualG,
    warnings,
    elementPositions
  };
};

export const formatMm = (val: number): string => {
  return Math.round(val).toString();
};

