import { AppConfig, CalculationResult } from '../types';

/**
 * Расчет разметки.
 * Элементы распределяются равномерно: все зазоры (между краями и между элементами) равны.
 */
export const calculateLayout = (config: AppConfig): CalculationResult => {
  const {
    diameter,
    distanceMode,
    distanceValue,
    elementType,
    boardWidth,
    distributionMode,
    targetGap,
    elementCount: manualCount,
    maxEndGap
  } = config;

  // Значения в мм
  const D = diameter;
  const V = distanceValue;
  const W = elementType === 'point' ? 0 : boardWidth;
  const M = maxEndGap;

  let S: number; // Расстояние между внутренними краями платформ
  let L: number; // Расстояние между центрами платформ

  if (distanceMode === 'center-to-center') {
    L = V;
    S = L - D;
  } else {
    S = V;
    L = S + D;
  }

  const warnings: string[] = [];
  if (S < 0) warnings.push('Дистанция слишком мала (отрицательная)');

  let N = manualCount;

  if (distributionMode === 'by-gap' && S > 0) {
    // 1. Находим идеальное N для желаемого отступа G_target
    // Формула равномерного распределения: S = (N + 1) * G + N * W
    // Отсюда G = (S - N*W) / (N + 1)
    // Чтобы G было близко к G_target: N = (S - G_target) / (G_target + W)
    const nIdeal = (S - targetGap) / (targetGap + W);
    N = Math.round(nIdeal);
    if (N < 0) N = 0;

    // 2. Проверяем ограничение M (макс. отступ). 
    // Если текущий G > M, нужно увеличивать N до тех пор, пока G <= M.
    // N_min = (S - M) / (M + W)
    const nMin = Math.ceil((S - M) / (M + W));
    if (N < nMin) {
      N = nMin;
    }
  }

  // Пересчитываем фактический зазор для выбранного N
  let actualG = 0;
  if (S > 0) {
    const totalElementWidth = N * W;
    const availableForGaps = S - totalElementWidth;
    actualG = availableForGaps / (N + 1);
  } else {
    actualG = 0;
  }

  // Ошибки
  if (actualG < 0) {
    warnings.push('Элементы не помещаются (увеличьте расстояние или уменьшите количество)');
  }

  // Строгая проверка: зазор не может быть больше M
  if (actualG > M + 0.01) {
    warnings.push(`Нарушен максимальный отступ от края платформы (превышает ${M} мм)`);
  }

  // Координаты начала каждого элемента относительно внутреннего края первой платформы
  const elementPositions: number[] = [];
  for (let i = 1; i <= N; i++) {
    const pos = actualG * i + W * (i - 1);
    elementPositions.push(pos);
  }

  return {
    edgeToEdge: S,
    centerToCenter: L,
    actualGap: actualG,
    elementCount: N,
    firstElementOffset: actualG,
    warnings,
    elementPositions
  };
};

export const formatMm = (val: number): string => {
  return Math.round(val).toString();
};

