import React from 'react';
import { AppConfig, CalculationResult } from '../types';
import { formatMm } from '../utils/calculations';

interface MainDiagramProps {
  config: AppConfig;
  result: CalculationResult;
}

export const MainDiagram: React.FC<MainDiagramProps> = ({ config, result }) => {
  const { diameter, elementType, boardWidth, showDimensions } = config;
  const { edgeToEdge, elementPositions, actualGap } = result;

  const padding = 600; 
  const circleRadius = diameter / 2;
  const canvasWidth = edgeToEdge + diameter * 2 + padding * 2;
  const canvasHeight = diameter + padding * 2;

  const viewWidth = 1000;
  const scale = viewWidth / canvasWidth;
  const viewHeight = canvasHeight * scale;

  const renderDimension = (x1: number, x2: number, y: number, label: string, color: string = "#64748b") => {
    if (!showDimensions) return null;
    const midX = (x1 + x2) / 2;
    return (
      <g>
        <line x1={x1} y1={y} x2={x2} y2={y} stroke={color} strokeWidth="1" />
        <line x1={x1} y1={y - 5} x2={x1} y2={y + 5} stroke={color} strokeWidth="1" />
        <line x1={x2} y1={y - 5} x2={x2} y2={y + 5} stroke={color} strokeWidth="1" />
        <text x={midX} y={y - 8} textAnchor="middle" className="text-[10px] font-bold" fill={color}>{label}</text>
      </g>
    );
  };

  return (
    <div className="w-full bg-white rounded-xl shadow-sm border border-slate-200 p-6 overflow-x-auto">
      <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-4">Чертеж (мм)</h3>
      <div className="min-w-[700px]">
        <svg viewBox={`0 0 ${viewWidth} ${viewHeight}`} className="w-full h-auto">
          {/* Axis */}
          <line x1={0} y1={viewHeight / 2} x2={viewWidth} y2={viewHeight / 2} stroke="#f1f5f9" strokeWidth="1" strokeDasharray="10,5" />

          {/* Platforms */}
          <g>
            <circle cx={(padding + circleRadius) * scale} cy={viewHeight / 2} r={circleRadius * scale} fill="#f8fafc" stroke="#64748b" strokeWidth="2" />
            <circle cx={(padding + circleRadius + diameter + edgeToEdge) * scale} cy={viewHeight / 2} r={circleRadius * scale} fill="#f8fafc" stroke="#64748b" strokeWidth="2" />
          </g>

          {/* Working line */}
          <line x1={(padding + diameter) * scale} y1={viewHeight / 2} x2={(padding + diameter + edgeToEdge) * scale} y2={viewHeight / 2} stroke="#3b82f6" strokeWidth="1" strokeDasharray="4,4" />

          {/* Elements */}
          {elementPositions.map((pos, idx) => {
            const x = (padding + diameter + pos) * scale;
            if (elementType === 'point') {
              return <circle key={idx} cx={x} cy={viewHeight / 2} r="5" fill="#ef4444" stroke="white" strokeWidth="1" />;
            } else {
              const width = boardWidth * scale;
              const height = (diameter / 1.5) * scale;
              return <rect key={idx} x={x} y={viewHeight / 2 - height / 2} width={width} height={height} fill="#ef4444" rx="2" stroke="white" strokeWidth="1" />;
            }
          })}

          {/* Dimensions */}
          {showDimensions && (
            <g>
              {/* Total edge-to-edge */}
              {renderDimension(
                (padding + diameter) * scale, 
                (padding + diameter + edgeToEdge) * scale, 
                viewHeight - 20, 
                `Всего: ${formatMm(edgeToEdge)} мм`,
                "#334155"
              )}

              {/* 1st Offset */}
              {renderDimension(
                (padding + diameter) * scale, 
                (padding + diameter + actualGap) * scale, 
                viewHeight / 2 - 40, 
                formatMm(actualGap),
                "#3b82f6"
              )}

              {/* Gap between 1st and 2nd elements (if exist) */}
              {elementPositions.length > 1 && renderDimension(
                (padding + diameter + actualGap + (elementType === 'board' ? boardWidth : 0)) * scale,
                (padding + diameter + actualGap + (elementType === 'board' ? boardWidth : 0) + actualGap) * scale,
                viewHeight / 2 - 40,
                formatMm(actualGap),
                "#3b82f6"
              )}

              {/* Last Offset */}
              {renderDimension(
                (padding + diameter + edgeToEdge - actualGap) * scale,
                (padding + diameter + edgeToEdge) * scale,
                viewHeight / 2 - 40,
                formatMm(actualGap),
                "#3b82f6"
              )}
            </g>
          )}
        </svg>
      </div>
    </div>
  );
};

import { AppConfig, CalculationResult } from '../types';

export const calculateLayout = (config: AppConfig): CalculationResult => {
  const {
    diameter,
    distanceMode,
    distanceValue,
    elementType,
    boardWidth,
    distributionMode,
    targetGap,
    elementCount: manualCount,
    maxEndGap
  } = config;

  const D = diameter;
  const V = distanceValue;
  const W = elementType === 'point' ? 0 : boardWidth;
  const M = maxEndGap;

  let S: number; // Edge-to-edge distance
  let L: number; // Center-to-center distance

  if (distanceMode === 'center-to-center') {
    L = V;
    S = L - D;
  } else {
    S = V;
    L = S + D;
  }

  const warnings: string[] = [];
  if (S < 0) warnings.push('Дистанция слишком мала');

  let N = manualCount;

  if (distributionMode === 'by-gap' && S > 0) {
    // We aim for G_edge <= M and G_inner ≈ targetGap.
    // Assuming symmetric layout: S = 2*G_edge + N*W + (N-1)*G_inner
    // To minimize N while satisfying G_edge <= M, we assume G_edge is either Tg or M.
    // If we assume G_edge = M: N ≈ (S - 2M + Tg) / (Tg + W)
    const nIdeal = (S - 2 * Math.min(targetGap, M) + targetGap) / (targetGap + W);
    N = Math.max(0, Math.round(nIdeal));

    // Safety check: if N is too low such that even with max M the gap is too large
    // G_pure_uniform = (S - NW) / (N+1). If this > M, we must increase N.
    while (N < 500 && (S - N * W) / (N + 1) > M + 0.1) {
      N++;
    }
  }

  let actualG_edge = 0;
  let actualG_inner = 0;

  if (S > 0 && N > 0) {
    // Calculate gaps.
    // Pure uniform gap if all were equal:
    const Gu = (S - N * W) / (N + 1);

    if (Gu <= M + 0.1) {
      // If uniform distribution naturally satisfies the M constraint, use it.
      actualG_edge = Gu;
      actualG_inner = Gu;
    } else {
      // Fix edge gaps at M, distribute the rest internally.
      actualG_edge = M;
      if (N > 1) {
        actualG_inner = (S - 2 * M - N * W) / (N - 1);
      } else {
        // Only one element: center it
        actualG_edge = (S - W) / 2;
        actualG_inner = 0;
      }
    }
  }

  if (actualG_edge < 0 || (N > 1 && actualG_inner < 0)) {
    warnings.push('Элементы не помещаются');
  }

  if (actualG_edge > M + 0.1) {
    warnings.push(`1-й отступ (${Math.round(actualG_edge)} мм) превышает макс. отступ (${M} мм)`);
  }

  const elementPositions: number[] = [];
  for (let i = 0; i < N; i++) {
    // pos is distance from the start of the working zone to the start of element i
    const pos = actualG_edge + i * (W + actualG_inner);
    elementPositions.push(pos);
  }

  return {
    edgeToEdge: S,
    centerToCenter: L,
    actualGap: N > 1 ? actualG_inner : actualG_edge,
    elementCount: N,
    firstElementOffset: actualG_edge,
    warnings,
    elementPositions
  };
};

export const formatMm = (val: number): string => {
  return Math.round(val).toString();
};

