export type ElementType = 'point' | 'board' | 'calculated';
export type DistanceMode = 'center-to-center' | 'edge-to-edge';
export type DistributionMode = 'by-gap' | 'by-count';
export type RulerMarkMode = 'center' | 'edge';

export interface AppConfig {
  diameter: number;
  distanceMode: DistanceMode;
  distanceValue: number;
  elementType: ElementType;
  boardWidth: number;
  distributionMode: DistributionMode;
  targetGap: number;
  elementCount: number;
  maxEndGap: number;
  rulerMarkMode: RulerMarkMode;
  showDimensions: boolean;
}

export interface CalculationResult {
  edgeToEdge: number;
  centerToCenter: number;
  actualGap: number;
  elementCount: number;
  firstElementOffset: number;
  warnings: string[];
  elementPositions: number[]; // relative to the inner edge of the first circle
}

import { AppConfig, CalculationResult } from '../types';

export const calculateLayout = (config: AppConfig): CalculationResult => {
  const {
    diameter,
    distanceMode,
    distanceValue,
    elementType,
    boardWidth,
    distributionMode,
    targetGap,
    elementCount: manualCount,
    maxEndGap
  } = config;

  const D = diameter;
  const V = distanceValue;
  // 'calculated' uses boardWidth which is managed by state logic
  const W = elementType === 'point' ? 0 : boardWidth;
  const M = maxEndGap;

  let S: number; // Edge-to-edge distance
  let L: number; // Center-to-center distance

  if (distanceMode === 'center-to-center') {
    L = V;
    S = L - D;
  } else {
    S = V;
    L = S + D;
  }

  const warnings: string[] = [];
  if (S < 0) warnings.push('Дистанция слишком мала');

  let N = manualCount;

  if (distributionMode === 'by-gap' && S > 0 && elementType !== 'calculated') {
    const effectiveEdge = Math.min(M, targetGap);
    const nIdeal = (S - 2 * effectiveEdge + targetGap) / (targetGap + W);
    N = Math.max(1, Math.round(nIdeal));
  }

  let actualG_edge = 0;
  let actualG_inner = 0;

  if (S > 0 && N > 0) {
    // Try uniform distribution first
    const Gu = (S - N * W) / (N + 1);

    // For calculated mode, we strictly follow the boardWidth derived in the UI
    if (elementType === 'calculated') {
      actualG_edge = targetGap;
      actualG_inner = targetGap;
    } else if (Gu <= M + 0.1) {
      actualG_edge = Gu;
      actualG_inner = Gu;
    } else {
      actualG_edge = M;
      if (N > 1) {
        actualG_inner = (S - 2 * M - N * W) / (N - 1);
      } else {
        actualG_edge = (S - W) / 2;
        actualG_inner = 0;
      }
    }
  }

  if (actualG_edge < 0 || (N > 1 && actualG_inner < 0)) {
    warnings.push('Элементы не помещаются');
  }

  if (elementType !== 'calculated' && actualG_edge > M + 0.5) {
    warnings.push(`1-й отступ (${Math.round(actualG_edge)} мм) превышает макс. отступ (${M} мм)`);
  }

  const elementPositions: number[] = [];
  for (let i = 0; i < N; i++) {
    const pos = actualG_edge + i * (W + (N > 1 ? actualG_inner : 0));
    elementPositions.push(pos);
  }

  return {
    edgeToEdge: S,
    centerToCenter: L,
    actualGap: N > 1 ? actualG_inner : actualG_edge,
    elementCount: N,
    firstElementOffset: actualG_edge,
    warnings,
    elementPositions
  };
};

export const formatMm = (val: number): string => {
  return Math.round(val).toString();
};

import React, { useState, useEffect } from 'react';
import { 
  Circle, 
  ArrowLeftRight, 
  Box, 
  LayoutGrid, 
  AlertTriangle, 
  Settings2, 
  Image as ImageIcon, 
  Share2, 
  Plus, 
  Minus,
  Maximize2,
  Calculator
} from 'lucide-react';
import { AppConfig, ElementType } from './types';
import { calculateLayout } from './utils/calculations';
import { MainDiagram } from './components/MainDiagram';
import { ConstructionRuler } from './components/ConstructionRuler';

const STORAGE_KEY = 'construction_layout_config';

const INITIAL_STATE: AppConfig = {
  diameter: 1500,
  distanceMode: 'center-to-center',
  distanceValue: 12000,
  elementType: 'point',
  boardWidth: 145,
  distributionMode: 'by-gap',
  targetGap: 400,
  elementCount: 5,
  maxEndGap: 300,
  rulerMarkMode: 'edge',
  showDimensions: true,
};

const App: React.FC = () => {
  const [isExporting, setIsExporting] = useState(false);
  const [config, setConfig] = useState<AppConfig>(() => {
    try {
      const hash = window.location.hash.substring(1);
      if (hash) {
        return { ...INITIAL_STATE, ...JSON.parse(decodeURIComponent(hash)) };
      }
    } catch (e) {}
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        return { ...INITIAL_STATE, ...JSON.parse(saved) };
      }
    } catch (e) {}
    return INITIAL_STATE;
  });

  const [result, setResult] = useState(calculateLayout(config));

  useEffect(() => {
    const newResult = calculateLayout(config);
    setResult(newResult);

    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(config));
      const configString = JSON.stringify(config);
      const encodedConfig = encodeURIComponent(configString);
      if (window.location.hash !== `#${encodedConfig}`) {
        window.location.hash = encodedConfig;
      }
    } catch (e) {}
  }, [config]);

  const updateConfig = (updates: Partial<AppConfig>) => {
    setConfig(prev => ({ ...prev, ...updates }));
  };

  // Logic to calculate width based on S, G, and N
  const deriveWidth = (S: number, G: number, N: number) => {
    if (N <= 0) return 0;
    // S = (N + 1) * G + N * W => W = (S - (N + 1) * G) / N
    const W = (S - (N + 1) * G) / N;
    return Math.max(0, Math.round(W));
  };

  const handleTargetGapChange = (value: number) => {
    if (config.elementType === 'calculated') {
      const newWidth = deriveWidth(result.edgeToEdge, value, config.elementCount);
      updateConfig({ targetGap: value, boardWidth: newWidth });
    } else {
      updateConfig({ targetGap: value, distributionMode: 'by-gap' });
    }
  };

  const handleElementCountChange = (value: number) => {
    const newCount = Math.max(0, value);
    if (config.elementType === 'calculated') {
      const newWidth = deriveWidth(result.edgeToEdge, config.targetGap, newCount);
      updateConfig({ elementCount: newCount, boardWidth: newWidth });
    } else {
      const tempConfig = { ...config, elementCount: newCount, distributionMode: 'by-count' as const };
      const tempResult = calculateLayout(tempConfig);
      updateConfig({
        elementCount: newCount,
        distributionMode: 'by-count',
        targetGap: Math.round(tempResult.actualGap)
      });
    }
  };

  const handleAdjustCount = (delta: number) => {
    handleElementCountChange(config.elementCount + delta);
  };

  const handleElementTypeChange = (type: ElementType) => {
    if (type === 'calculated') {
      const newWidth = deriveWidth(result.edgeToEdge, config.targetGap, config.elementCount);
      updateConfig({ elementType: type, boardWidth: newWidth, distributionMode: 'by-count' });
    } else {
      updateConfig({ elementType: type });
    }
  };

  const handleSetUniformGaps = () => {
    updateConfig({ maxEndGap: Math.round(result.actualGap) });
  };

  const handleExportImage = async () => {
    const element = document.getElementById('export-container');
    if (!element) return;
    setIsExporting(true);
    try {
      await new Promise(r => setTimeout(r, 200));
      const canvas = await (window as any).html2canvas(element, { scale: 2, backgroundColor: '#f8fafc', logging: false, useCORS: true });
      const image = canvas.toDataURL("image/png");
      const link = document.createElement('a');
      link.href = image;
      link.download = `razmetka-${Date.now()}.png`;
      link.click();
    } catch (error) {
      console.error('Export failed:', error);
      alert('Ошибка при создании изображения.');
    } finally { setIsExporting(false); }
  };

  const handleShare = () => {
    navigator.clipboard.writeText(window.location.href);
    alert('Ссылка скопирована!');
  };

  const inputClasses = "w-full bg-white border border-slate-300 rounded-lg px-2 py-1.5 text-sm text-slate-900 font-bold outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all shadow-sm";

  return (
