  const scale = viewWidth / canvasWidth;
  const viewHeight = canvasHeight * scale;

  const renderDimension = (x1: number, x2: number, y: number, label: string, color: string = "#64748b", isBelow = false) => {
    if (!showDimensions) return null;
    const midX = (x1 + x2) / 2;
    // Scaled text offsets to prevent overlaps
    const textY = isBelow ? y + (16 * scale * 10) : y - (10 * scale * 10);

    return (
      <g>
        <line x1={x1} y1={y} x2={x2} y2={y} stroke={color} strokeWidth="1.2" />
        <line x1={x1} y1={y - 6} x2={x1} y2={y + 6} stroke={color} strokeWidth="1.2" />
        <line x1={x2} y1={y - 6} x2={x2} y2={y + 6} stroke={color} strokeWidth="1.2" />
        <text 
          x={midX} 
          y={textY} 
          textAnchor="middle" 
          className="text-[11px] font-extrabold" 
          fill={color}
          style={{ fontSize: `${Math.max(10, 11 * (viewWidth / 1000))}px` }}
        >
          {label}
        </text>
      </g>
    );
  };

  const hasWidth = elementType !== 'point';
  // startX and endX are the "inner" edges of the platforms
  const startX = (paddingX + circleRadius) * scale;
  const endX = (paddingX + circleRadius + edgeToEdge) * scale;
  const centerY = viewHeight / 2;
  const scaledRadius = circleRadius * scale;

  return (
    <div className="w-full bg-white rounded-xl shadow-sm border border-slate-200 p-4">
      <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Схема (мм)</h3>
      <div className="w-full">
        <svg 
          viewBox={`0 0 ${viewWidth} ${viewHeight}`} 
          className="w-full h-auto" 
          style={{ display: 'block', maxHeight: '60vh' }}
        >
          {/* Axis */}
          <line x1={0} y1={centerY} x2={viewWidth} y2={centerY} stroke="#f1f5f9" strokeWidth="1" strokeDasharray="10,5" />

          {/* Half-Platform 1 (Left) - Arcing TOWARDS the center */}
          <path 
            d={`M ${startX},${centerY - scaledRadius} A ${scaledRadius},${scaledRadius} 0 0 1 ${startX},${centerY + scaledRadius} L ${startX - scaledRadius},${centerY + scaledRadius} L ${startX - scaledRadius},${centerY - scaledRadius} Z`} 
            fill="#f8fafc" 
            stroke="#94a3b8" 
            strokeWidth="2" 
          />

          {/* Half-Platform 2 (Right) - Arcing TOWARDS the center */}
          <path 
            d={`M ${endX},${centerY - scaledRadius} A ${scaledRadius},${scaledRadius} 0 0 0 ${endX},${centerY + scaledRadius} L ${endX + scaledRadius},${centerY + scaledRadius} L ${endX + scaledRadius},${centerY - scaledRadius} Z`} 
            fill="#f8fafc" 
            stroke="#94a3b8" 
            strokeWidth="2" 
          />

          {/* Working line */}
          <line x1={startX} y1={centerY} x2={endX} y2={centerY} stroke="#3b82f6" strokeWidth="1.5" strokeDasharray="4,4" />

          {/* Elements */}
          {elementPositions.map((pos, idx) => {
            const x = startX + pos * scale;
            if (elementType === 'point') {
              return <circle key={idx} cx={x} cy={centerY} r="5" fill="#ef4444" stroke="white" strokeWidth="1" />;
            } else {
              const width = boardWidth * scale;
              const height = (diameter / 1.5) * scale;
              return <rect key={idx} x={x} y={centerY - height / 2} width={width} height={height} fill="#ef4444" rx="2" stroke="white" strokeWidth="1" />;
            }
          })}

          {/* Dimensions */}
          {showDimensions && (
            <g>
              {/* Total edge-to-edge */}
              {renderDimension(
                startX, 
                endX, 
                viewHeight - 25, 
                `Рабочая зона: ${formatMm(edgeToEdge)} мм`,
                "#1e293b",
                true
              )}

              {/* 1st Offset */}
              {renderDimension(
                startX, 
                startX + firstElementOffset * scale, 
                centerY - 40, 
                `Отступ: ${formatMm(firstElementOffset)}`,
                "#2563eb"
              )}

              {/* Inner Gap */}
              {elementPositions.length > 1 && renderDimension(
                startX + (firstElementOffset + (hasWidth ? boardWidth : 0)) * scale,
                startX + (firstElementOffset + (hasWidth ? boardWidth : 0) + actualGap) * scale,
                centerY - 80, 
                `Шаг: ${formatMm(actualGap)}`,
                "#dc2626"
              )}

              {/* Dimension for board width */}
              {hasWidth && elementPositions.length > 0 && renderDimension(
                startX + firstElementOffset * scale,
                startX + (firstElementOffset + boardWidth) * scale,
                centerY + 85,
                `Ширина: ${formatMm(boardWidth)}`,
                "#4338ca",
                true
              )}
            </g>
          )}
        </svg>
      </div>
    </div>
  );
};

