import React from 'react';
import { AppConfig, CalculationResult } from '../types';
import { formatMm } from '../utils/calculations';

interface MainDiagramProps {
  config: AppConfig;
  result: CalculationResult;
}

export const MainDiagram: React.FC<MainDiagramProps> = ({ config, result }) => {
  const { diameter, elementType, boardWidth } = config;
  const { edgeToEdge, elementPositions, firstElementOffset, actualGap } = result;

  const circleRadius = diameter / 2;

  // Logical padding in mm (to accommodate labels above/below)
  const padX = 100;
  const padY = 400;

  // Viewport setup
  const viewWidth = 1000;
  const logicalWidth = diameter + edgeToEdge + padX * 2;
  const logicalHeight = diameter + padY * 2;
  const scale = viewWidth / logicalWidth;
  const viewHeight = logicalHeight * scale;

  const centerY = viewHeight / 2;
  const scaledRadius = circleRadius * scale;

  const startX = (padX + circleRadius) * scale;
  const endX = startX + (edgeToEdge * scale);

  const circleTop = centerY - scaledRadius;
  const circleBottom = centerY + scaledRadius;

  const renderDimension = (x1: number, x2: number, y: number, label: string, color: string = "#64748b", isBelow = false) => {
    const midX = (x1 + x2) / 2;
    // Labels are always visible now, fixed positioning within viewBox
    const textY = isBelow ? y + 30 : y - 15;

    return (
      <g>
        <line x1={x1} y1={y} x2={x2} y2={y} stroke={color} strokeWidth="3" />
        <line x1={x1} y1={y - 12} x2={x1} y2={y + 12} stroke={color} strokeWidth="3" />
        <line x1={x2} y1={y - 12} x2={x2} y2={y + 12} stroke={color} strokeWidth="3" />
        <text 
          x={midX} 
          y={textY} 
          textAnchor="middle" 
          className="font-black" 
          fill={color}
          style={{ 
            fontSize: '18px', 
            paintOrder: 'stroke', 
            stroke: 'white', 
            strokeWidth: '4px',
            filter: 'drop-shadow(0px 1px 2px rgba(0,0,0,0.1))' 
          }}
        >
          {label}
        </text>
      </g>
    );
  };

  const hasWidth = elementType !== 'point';
  const elemHeight = (diameter / 1.5) * scale;
  const elemTop = centerY - elemHeight / 2;
  const elemBottom = centerY + elemHeight / 2;

  return (
    <div className="w-full bg-white rounded-xl shadow-sm border border-slate-200 p-4">
      <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Схема (мм)</h3>
      <div className="w-full overflow-hidden">
        <svg 
          viewBox={`0 0 ${viewWidth} ${viewHeight}`} 
          className="w-full h-auto" 
          style={{ display: 'block', maxWidth: '100%' }}
        >
          {/* Axis */}
          <line x1={0} y1={centerY} x2={viewWidth} y2={centerY} stroke="#f1f5f9" strokeWidth="1" strokeDasharray="10,5" />

          {/* Left Platform - Facing Inward */}
          <path 
            d={`M ${startX - scaledRadius},${circleTop} 
               L ${startX - scaledRadius},${circleBottom} 
               A ${scaledRadius},${scaledRadius} 0 0 0 ${startX},${centerY}
               A ${scaledRadius},${scaledRadius} 0 0 0 ${startX - scaledRadius},${circleTop} Z`} 
            fill="#f1f5f9" 
            stroke="#94a3b8" 
            strokeWidth="3.5" 
          />

          {/* Right Platform - Facing Inward */}
          <path 
            d={`M ${endX + scaledRadius},${circleTop} 
               L ${endX + scaledRadius},${circleBottom} 
               A ${scaledRadius},${scaledRadius} 0 0 1 ${endX},${centerY}
               A ${scaledRadius},${scaledRadius} 0 0 1 ${endX + scaledRadius},${circleTop} Z`} 
            fill="#f1f5f9" 
            stroke="#94a3b8" 
            strokeWidth="3.5" 
          />

          {/* Connect axis */}
          <line x1={startX} y1={centerY} x2={endX} y2={centerY} stroke="#3b82f6" strokeWidth="2" strokeDasharray="8,4" />

          {/* Elements */}
          {elementPositions.map((pos, idx) => {
            const x = startX + (pos * scale);
            if (elementType === 'point') {
              return <circle key={idx} cx={x} cy={centerY} r="10" fill="#ef4444" stroke="white" strokeWidth="3" />;
            } else {
              const width = boardWidth * scale;
              return <rect key={idx} x={x} y={elemTop} width={width} height={elemHeight} fill="#ef4444" rx="4" stroke="white" strokeWidth="2.5" />;
            }
          })}

          {/* Dimension tiers (All offsets scaled by 'scale') */}
          <g>
            {/* Step: Top tier */}
            {elementPositions.length > 1 && renderDimension(
              startX + (firstElementOffset + (hasWidth ? boardWidth : 0)) * scale,
              startX + (firstElementOffset + (hasWidth ? boardWidth : 0) + actualGap) * scale,
              circleTop - (160 * scale), 
              `Шаг: ${formatMm(actualGap)}`,
              "#dc2626"
            )}

            {/* Offset: Above items */}
            {renderDimension(
              startX, 
              startX + (firstElementOffset * scale), 
              circleTop - (60 * scale), 
              `Отступ: ${formatMm(firstElementOffset)}`,
              "#2563eb"
            )}

            {/* Width: Below items */}
            {hasWidth && elementPositions.length > 0 && renderDimension(
              startX + (firstElementOffset * scale),
              startX + ((firstElementOffset + boardWidth) * scale),
              circleBottom + (60 * scale),
              `Ширина: ${formatMm(boardWidth)}`,
              "#7c3aed",
              true
            )}

            {/* Total: Bottom tier */}
            {renderDimension(
              startX, 
              endX, 
              circleBottom + (160 * scale), 
              `Всего: ${formatMm(edgeToEdge)} мм`,
              "#0f172a",
              true
            )}
          </g>
        </svg>
      </div>
    </div>
  );
};

import React from 'react';
import { AppConfig, CalculationResult } from '../types';
import { formatMm } from '../utils/calculations';

interface ConstructionRulerProps {
  config: AppConfig;
  result: CalculationResult;
}

export const ConstructionRuler: React.FC<ConstructionRulerProps> = ({ config, result }) => {
  const { elementPositions, edgeToEdge } = result;
  const { elementType, boardWidth } = config;

  // SVG parameters
  const margin = 50;
  const viewWidth = 1000;
  const viewHeight = 160;
  const usableWidth = viewWidth - (margin * 2);

  const getX = (pos: number) => {
    const ratio = edgeToEdge > 0 ? pos / edgeToEdge : 0;
    return margin + (ratio * usableWidth);
  };

  const hasWidth = elementType !== 'point';

  // Generate the bracketed string sequence
  const sequence = [
    'Край платформы',
    ...elementPositions.map(pos => formatMm(pos)),
    formatMm(edgeToEdge),
    'Край платформы'
  ];

  const rulerY = viewHeight - 40;

  return (
    <div className="w-full bg-white rounded-xl shadow-sm border border-slate-200 p-4">
      <div className="flex items-center justify-between mb-2">
        <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Линейка разметки (мм)</h3>
        <div className="flex gap-4 text-[9px] font-bold uppercase">
          <span className="flex items-center gap-1.5"><div className="w-2 h-2 bg-blue-500 rounded-full"></div> Платформа</span>
          <span className="flex items-center gap-1.5"><div className="w-2 h-2 bg-red-500 rounded-sm"></div> Элемент</span>
        </div>
      </div>

      <div className="w-full">
        <svg 
          viewBox={`0 0 ${viewWidth} ${viewHeight}`} 
          className="w-full h-auto"
          style={{ display: 'block' }}
        >
          {/* Main ruler line */}
          <line 
            x1={margin} 
            y1={rulerY} 
            x2={margin + usableWidth} 
            y2={rulerY} 
            stroke="#e2e8f0" 
            strokeWidth="3" 
          />

          {/* Zero point (First platform edge) */}
          <g>
            <line x1={margin} y1={rulerY - 20} x2={margin} y2={rulerY} stroke="#2563eb" strokeWidth="3" />
            <text x={margin} y={rulerY + 20} textAnchor="middle" className="text-[12px] font-black" fill="#1d4ed8">0</text>
          </g>

          {/* Element marks & width visualization */}
          {elementPositions.map((pos, idx) => {
            const x = getX(pos);
            const isHighDensity = elementPositions.length > 20;
            const labelY = rulerY - 45;

            return (
              <g key={idx}>
                {/* Element starting tick */}
                <line x1={x} y1={rulerY - 35} x2={x} y2={rulerY} stroke="#ef4444" strokeWidth="2" />

                {/* Visual footprint for board elements */}
                {hasWidth && (
                  <rect 
                    x={x} 
                    y={rulerY - 6} 
                    width={(boardWidth / edgeToEdge) * usableWidth} 
                    height="12" 
                    fill="#ef4444" 
                    rx="1"
                    className="opacity-90"
                  />
                )}

                <text 
                  x={x} 
                  y={labelY} 
                  textAnchor="start" 
                  className={`${isHighDensity ? 'text-[8px]' : 'text-[11px]'} font-black`} 
                  fill="#0f172a"
                  transform={`rotate(-60, ${x}, ${labelY})`}
                >
                  {formatMm(pos)}
                </text>
              </g>
            );
          })}

          {/* End point (Second platform edge) */}
          <g>
            <line x1={margin + usableWidth} y1={rulerY - 20} x2={margin + usableWidth} y2={rulerY} stroke="#2563eb" strokeWidth="3" />
            <text x={margin + usableWidth} y={rulerY + 20} textAnchor="middle" className="text-[12px] font-black" fill="#1d4ed8">{formatMm(edgeToEdge)}</text>
          </g>
        </svg>
      </div>

      <div className="mt-4 pt-4 border-t border-slate-100">
        <p className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter mb-2">Последовательность разметки:</p>
        <div className="flex flex-wrap gap-1">
          {sequence.map((item, idx) => (
            <span key={idx} className="bg-slate-50 border border-slate-200 px-1.5 py-0.5 rounded text-[11px] font-black text-slate-800">
              [{item}]
            </span>
          ))}
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { AppConfig, CalculationResult } from '../types';
import { formatMm } from '../utils/calculations';

interface MainDiagramProps {
  config: AppConfig;
  result: CalculationResult;
}

export const MainDiagram: React.FC<MainDiagramProps> = ({ config, result }) => {
  const { diameter, elementType, boardWidth } = config;
  const { edgeToEdge, elementPositions, firstElementOffset, actualGap } = result;

  const circleRadius = diameter / 2;

  // Logical padding in mm (to accommodate labels above/below)
  // Increased padY to ensure the new spacing for "Total" fits in view
  const padX = 100;
  const padY = 500;

  // Viewport setup
  const viewWidth = 1000;
  const logicalWidth = diameter + edgeToEdge + padX * 2;
  const logicalHeight = diameter + padY * 2;
  const scale = viewWidth / logicalWidth;
  const viewHeight = logicalHeight * scale;

  const centerY = viewHeight / 2;
  const scaledRadius = circleRadius * scale;

  const startX = (padX + circleRadius) * scale;
  const endX = startX + (edgeToEdge * scale);

  const circleTop = centerY - scaledRadius;
  const circleBottom = centerY + scaledRadius;

  const renderDimension = (x1: number, x2: number, y: number, label: string, color: string = "#64748b", isBelow = false) => {
    const midX = (x1 + x2) / 2;
    // Labels are always visible now, fixed positioning within viewBox
    const textY = isBelow ? y + 32 : y - 18;

    return (
      <g>
        <line x1={x1} y1={y} x2={x2} y2={y} stroke={color} strokeWidth="3" />
        <line x1={x1} y1={y - 12} x2={x1} y2={y + 12} stroke={color} strokeWidth="3" />
        <line x1={x2} y1={y - 12} x2={x2} y2={y + 12} stroke={color} strokeWidth="3" />
        <text 
          x={midX} 
          y={textY} 
          textAnchor="middle" 
          className="font-black" 
          fill={color}
          style={{ 
            fontSize: '18px', 
            paintOrder: 'stroke', 
            stroke: 'white', 
            strokeWidth: '4px',
            filter: 'drop-shadow(0px 1px 2px rgba(0,0,0,0.1))' 
          }}
        >
          {label}
        </text>
      </g>
    );
  };

  const hasWidth = elementType !== 'point';
  // Reduced height: diameter / 3 instead of 1.5
  const elemHeight = (diameter / 3) * scale;
  const elemTop = centerY - elemHeight / 2;
  const elemBottom = centerY + elemHeight / 2;

  return (
    <div className="w-full bg-white rounded-xl shadow-sm border border-slate-200 p-4">
      <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Схема (мм)</h3>
      <div className="w-full overflow-hidden">
        <svg 
          viewBox={`0 0 ${viewWidth} ${viewHeight}`} 
          className="w-full h-auto" 
          style={{ display: 'block', maxWidth: '100%' }}
        >
          {/* Axis */}
          <line x1={0} y1={centerY} x2={viewWidth} y2={centerY} stroke="#f1f5f9" strokeWidth="1" strokeDasharray="10,5" />

          {/* Left Platform - Facing Inward */}
          <path 
            d={`M ${startX - scaledRadius},${circleTop} 
               L ${startX - scaledRadius},${circleBottom} 
               A ${scaledRadius},${scaledRadius} 0 0 0 ${startX},${centerY}
               A ${scaledRadius},${scaledRadius} 0 0 0 ${startX - scaledRadius},${circleTop} Z`} 
            fill="#f1f5f9" 
            stroke="#94a3b8" 
            strokeWidth="3.5" 
          />

          {/* Right Platform - Facing Inward */}
          <path 
            d={`M ${endX + scaledRadius},${circleTop} 
               L ${endX + scaledRadius},${circleBottom} 
               A ${scaledRadius},${scaledRadius} 0 0 1 ${endX},${centerY}
               A ${scaledRadius},${scaledRadius} 0 0 1 ${endX + scaledRadius},${circleTop} Z`} 
            fill="#f1f5f9" 
            stroke="#94a3b8" 
            strokeWidth="3.5" 
          />

          {/* Connect axis */}
          <line x1={startX} y1={centerY} x2={endX} y2={centerY} stroke="#3b82f6" strokeWidth="2" strokeDasharray="8,4" />

          {/* Elements */}
          {elementPositions.map((pos, idx) => {
            const x = startX + (pos * scale);
            if (elementType === 'point') {
              return <circle key={idx} cx={x} cy={centerY} r="10" fill="#ef4444" stroke="white" strokeWidth="3" />;
            } else {
              const width = boardWidth * scale;
              return <rect key={idx} x={x} y={elemTop} width={width} height={elemHeight} fill="#ef4444" rx="4" stroke="white" strokeWidth="2.5" />;
            }
          })}

          {/* Dimension tiers (All offsets scaled by 'scale') */}
          <g>
            {/* Step: Top tier */}
            {elementPositions.length > 1 && renderDimension(
              startX + (firstElementOffset + (hasWidth ? boardWidth : 0)) * scale,
              startX + (firstElementOffset + (hasWidth ? boardWidth : 0) + actualGap) * scale,
              circleTop - (160 * scale), 
              `Шаг: ${formatMm(actualGap)}`,
              "#dc2626"
            )}

            {/* Offset: Above items */}
            {renderDimension(
              startX, 
              startX + (firstElementOffset * scale), 
              circleTop - (60 * scale), 
              `Отступ: ${formatMm(firstElementOffset)}`,
              "#2563eb"
            )}

            {/* Width: Below items */}
            {hasWidth && elementPositions.length > 0 && renderDimension(
              startX + (firstElementOffset * scale),
              startX + ((firstElementOffset + boardWidth) * scale),
              circleBottom + (60 * scale),
              `Ширина: ${formatMm(boardWidth)}`,
              "#7c3aed",
              true
            )}

            {/* Total: Bottom tier - Increased distance from circleBottom to avoid overlap with Width label */}
            {renderDimension(
              startX, 
              endX, 
              circleBottom + (220 * scale), 
              `Всего: ${formatMm(edgeToEdge)} мм`,
              "#0f172a",
              true
            )}
          </g>
        </svg>
      </div>
    </div>
  );
};

