              "#7c3aed",
              true
            )}

            {/* Tier 4 (Bottom): Total - Lowest */}
            {renderDimension(
              startX, 
              endX, 
              tierTotal, 
              `Всего: ${formatMm(edgeToEdge)} мм`,
              "#0f172a",
              true
            )}
          </g>
        </svg>
      </div>
    </div>
  );
};

