                disabled={config.isMaxEndGapLocked}
                className={`${inputClasses} ${config.isMaxEndGapLocked ? 'bg-blue-50/50 border-blue-200 text-blue-800 cursor-not-allowed' : ''}`} 
              />
              {config.isMaxEndGapLocked && (
                <p className="text-[9px] text-blue-500 font-bold italic mt-1 leading-tight tracking-tight uppercase">Авто-синхронизация с текущим шагом активна</p>
