const STORAGE_KEY = 'construction_layout_config';

const INITIAL_STATE: AppConfig = {
  diameter: 1500,
  distanceMode: 'center-to-center',
  distanceValue: 12000,
  elementType: 'point',
  boardWidth: 145,
  distributionMode: 'by-gap',
  targetGap: 400,
  elementCount: 5,
  maxEndGap: 300,
  isMaxEndGapLocked: false,
  rulerMarkMode: 'edge',
};

// Compact serialization for shorter URLs
const serializeConfig = (c: AppConfig): string => {
  const dm = c.distanceMode === 'center-to-center' ? 0 : 1;
  const et = c.elementType === 'point' ? 0 : c.elementType === 'board' ? 1 : 2;
  const db = c.distributionMode === 'by-gap' ? 0 : 1;
  const lock = c.isMaxEndGapLocked ? 1 : 0;
  const rm = c.rulerMarkMode === 'edge' ? 0 : 1;
  return `v2_${c.diameter}_${dm}_${c.distanceValue}_${et}_${c.boardWidth}_${db}_${c.targetGap}_${c.elementCount}_${c.maxEndGap}_${lock}_${rm}`;
};

const deserializeConfig = (s: string): Partial<AppConfig> | null => {
  if (!s.startsWith('v2_')) return null;
  const parts = s.split('_');
  if (parts.length < 12) return null;
  return {
    diameter: Number(parts[1]),
    distanceMode: parts[2] === '0' ? 'center-to-center' : 'edge-to-edge',
    distanceValue: Number(parts[3]),
    elementType: parts[4] === '0' ? 'point' : parts[4] === '1' ? 'board' : 'calculated',
    boardWidth: Number(parts[5]),
    distributionMode: parts[6] === '0' ? 'by-gap' : 'by-count',
    targetGap: Number(parts[7]),
    elementCount: Number(parts[8]),
    maxEndGap: Number(parts[9]),
    isMaxEndGapLocked: parts[10] === '1',
    rulerMarkMode: parts[11] === '0' ? 'edge' : 'center',
  };
};

