                >
                  {config.isMaxEndGapLocked ? <Lock className="w-2.5 h-2.5" /> : <Unlock className="w-2.5 h-2.5" />}
                  {t.syncTarget}
                </button>
              </div>
              <input 
                type="number" 
                value={config.isMaxEndGapLocked ? config.targetGap : config.maxEndGap} 
