import React, { useState, useEffect } from 'react';
import QRCode from 'https://esm.sh/qrcode';
import { AppConfig, CalculationResult } from '../types';
import { formatMm } from '../utils/calculations';
import { serializeConfig } from '../utils/serialization';

interface MainDiagramProps {
  config: AppConfig;
  result: CalculationResult;
  lang: 'ru' | 'en';
}

const LABELS = {
  ru: {
    step: 'Шаг',
    offset: 'Отступ',
    width: 'Ширина',
    total: 'Всего',
    diagram: 'Схема',
    scan: 'Сканируй для перехода'
  },
  en: {
    step: 'Step',
    offset: 'Offset',
    width: 'Width',
    total: 'Total',
    diagram: 'Diagram',
    scan: 'Scan to open'
  }
};

export const MainDiagram: React.FC<MainDiagramProps> = ({ config, result, lang }) => {
  const { elementType, boardWidth } = config;
  const { edgeToEdge, elementPositions, firstElementOffset, actualGap } = result;
  const t = LABELS[lang];

  const [qrUrl, setQrUrl] = useState<string>('');

  // Генерируем QR-код на основе актуального объекта config
  useEffect(() => {
    const timer = setTimeout(() => {
      const baseUrl = 'https://kekspetrovich.github.io/RopeParkSpacingCalculator/';
      // Генерируем URL напрямую из config, не дожидаясь обновления window.location.hash
      const encodedConfig = serializeConfig(config);
      const fullUrl = `${baseUrl}#${encodedConfig}`;

      QRCode.toDataURL(fullUrl, {
        margin: 1,
        width: 180, 
        color: {
          dark: '#0f172a',
          light: '#ffffff'
        },
        errorCorrectionLevel: 'L'
      })
      .then(url => setQrUrl(url))
      .catch(err => console.error('QR Generation failed', err));
    }, 100); // Небольшая задержка для плавности UI
    return () => clearTimeout(timer);
  }, [config]);

  // --- SVG КООРДИНАТЫ (0-1000 x 0-500) ---
  const viewWidth = 1000;
  const viewHeight = 500;
  const centerY = 250;

  const sideMargin = 80;
  const platformWidth = 50; 

  const startX = sideMargin + platformWidth; 
  const endX = viewWidth - sideMargin - platformWidth; 

  const usableWidth = endX - startX;
  const scale = edgeToEdge > 0 ? usableWidth / edgeToEdge : 1;

  const platformVisualHeight = 120;
  const elemVisualHeight = 50;
  const platformTop = centerY - platformVisualHeight / 2;
  const platformBottom = centerY + platformVisualHeight / 2;
  const elemTop = centerY - elemVisualHeight / 2;

  const renderDimension = (x1: number, x2: number, y: number, label: string, color: string = "#64748b", isBelow = false) => {
    const midX = (x1 + x2) / 2;
    const textYOffset = isBelow ? 28 : -15;

    return (
      <g>
        <line x1={x1} y1={y} x2={x2} y2={y} stroke={color} strokeWidth="2" />
        <line x1={x1} y1={y - 10} x2={x1} y2={y + 10} stroke={color} strokeWidth="2" />
        <line x1={x2} y1={y - 10} x2={x2} y2={y + 10} stroke={color} strokeWidth="2" />
        <text 
          x={midX} 
          y={y + textYOffset} 
          textAnchor="middle" 
          className="font-bold" 
          fill={color}
          style={{ 
            fontSize: '16px', 
            paintOrder: 'stroke', 
            stroke: 'white', 
            strokeWidth: '4px'
          }}
        >
          {label}
        </text>
      </g>
    );
  };

  const hasWidth = elementType !== 'point';
  const yStep = 90;
  const yOffset = 165;
  const yWidth = 335;
  const yTotal = 410;

  return (
    <div className="w-full bg-white rounded-xl shadow-sm border border-slate-200 p-4 relative overflow-hidden">
      <div className="flex justify-between items-start mb-4">
        <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{t.diagram} (мм)</h3>
      </div>

      <div className="w-full overflow-hidden">
        <svg 
          viewBox={`0 0 ${viewWidth} ${viewHeight}`} 
          className="w-full h-auto" 
          style={{ display: 'block', maxWidth: '100%' }}
        >
          {/* QR Code integration in SVG */}
          {qrUrl && (
            <g transform={`translate(${viewWidth - 170}, 0)`}>
              <rect x="0" y="0" width="160" height="160" fill="white" />
              <image href={qrUrl} x="0" y="0" width="160" height="160" />
              <text x="80" y="175" textAnchor="middle" className="text-[11px] font-black fill-slate-400 uppercase tracking-tighter">
                {t.scan}
              </text>
            </g>
          )}

          <line x1={0} y1={centerY} x2={viewWidth} y2={centerY} stroke="#f1f5f9" strokeWidth="1" strokeDasharray="10,5" />

          <path 
            d={`M ${startX - platformWidth},${platformTop} 
               L ${startX - platformWidth},${platformBottom} 
               A ${platformWidth},${platformVisualHeight/2} 0 0 0 ${startX},${centerY}
               A ${platformWidth},${platformVisualHeight/2} 0 0 0 ${startX - platformWidth},${platformTop} Z`} 
            fill="#f8fafc" 
            stroke="#94a3b8" 
            strokeWidth="3" 
          />

          <path 
            d={`M ${endX + platformWidth},${platformTop} 
               L ${endX + platformWidth},${platformBottom} 
               A ${platformWidth},${platformVisualHeight/2} 0 0 1 ${endX},${centerY}
               A ${platformWidth},${platformVisualHeight/2} 0 0 1 ${endX + platformWidth},${platformTop} Z`} 
            fill="#f8fafc" 
            stroke="#94a3b8" 
            strokeWidth="3" 
          />

          <line x1={startX} y1={centerY} x2={endX} y2={centerY} stroke="#0f172a" strokeWidth="1" strokeDasharray="8,4" />

          {elementPositions.map((pos, idx) => {
            const x = startX + (pos * scale);
            if (elementType === 'point') {
              return <circle key={idx} cx={x} cy={centerY} r="10" fill="#ef4444" stroke="white" strokeWidth="3" />;
            } else {
              const width = boardWidth * scale;
              return <rect key={idx} x={x} y={elemTop} width={width} height={elemVisualHeight} fill="#ef4444" rx="3" stroke="white" strokeWidth="2" />;
            }
          })}

          <g>
            {elementPositions.length > 1 && renderDimension(
              startX + (firstElementOffset + (hasWidth ? boardWidth : 0)) * scale,
              startX + (firstElementOffset + (hasWidth ? boardWidth : 0) + actualGap) * scale,
              yStep, 
              `${t.step}: ${formatMm(actualGap)}`,
              "#dc2626"
            )}

            {renderDimension(
              startX, 
              startX + (firstElementOffset * scale), 
              yOffset, 
              `${t.offset}: ${formatMm(firstElementOffset)}`,
              "#2563eb"
            )}

            {hasWidth && elementPositions.length > 0 && renderDimension(
              startX + (firstElementOffset * scale),
              startX + ((firstElementOffset + boardWidth) * scale),
              yWidth,
              `${t.width}: ${formatMm(boardWidth)}`,
              "#7c3aed",
              true
            )}

            {renderDimension(
              startX, 
              endX, 
              yTotal, 
              `${t.total}: ${formatMm(edgeToEdge)} мм`,
              "#0f172a",
              true
            )}
          </g>
        </svg>
      </div>
    </div>
  );
};

import { AppConfig } from '../types';

// Compact serialization for shorter URLs
export const serializeConfig = (c: AppConfig): string => {
  const dm = c.distanceMode === 'center-to-center' ? 0 : 1;
  const et = c.elementType === 'point' ? 0 : c.elementType === 'board' ? 1 : 2;
  const db = c.distributionMode === 'by-gap' ? 0 : 1;
  const lock = c.isMaxEndGapLocked ? 1 : 0;
  const rm = c.rulerMarkMode === 'edge' ? 0 : 1;

  // Собираем все важные параметры в строку
  return `v2_${c.diameter}_${dm}_${c.distanceValue}_${et}_${c.boardWidth}_${db}_${c.targetGap}_${c.elementCount}_${c.maxEndGap}_${lock}_${rm}`;
};

export const deserializeConfig = (s: string): Partial<AppConfig> | null => {
  if (!s || !s.startsWith('v2_')) return null;
  const parts = s.split('_');
  if (parts.length < 12) return null;

  const getNum = (val: string, fallback: number) => {
    const n = Number(val);
    return isNaN(n) ? fallback : n;
  };

  return {
    diameter: getNum(parts[1], 1500),
    distanceMode: parts[2] === '0' ? 'center-to-center' : 'edge-to-edge',
    distanceValue: getNum(parts[3], 12000),
    elementType: parts[4] === '0' ? 'point' : parts[4] === '1' ? 'board' : 'calculated',
    boardWidth: getNum(parts[5], 145),
    distributionMode: parts[6] === '0' ? 'by-gap' : 'by-count',
    targetGap: getNum(parts[7], 400),
    elementCount: getNum(parts[8], 5),
    maxEndGap: getNum(parts[9], 300),
    isMaxEndGapLocked: parts[10] === '1',
    rulerMarkMode: parts[11] === '0' ? 'edge' : 'center',
  };
};

