    stepBetween: 'Step between elements'
  }
};

const App: React.FC = () => {
  const [lang, setLang] = useState<'ru' | 'en'>(() => {
    const saved = localStorage.getItem('app_lang');
    return (saved === 'en' || saved === 'ru') ? saved : 'ru';
  });

  const t = TRANSLATIONS[lang];
  const [isExporting, setIsExporting] = useState(false);

  const [config, setConfig] = useState<AppConfig>(() => {
    let base = INITIAL_STATE;
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) base = { ...base, ...JSON.parse(saved) };
    } catch (e) {}

    try {
      const hash = window.location.hash.substring(1);
      if (hash) {
        if (hash.startsWith('v2_') || hash.startsWith('v3_')) {
          const deserialized = deserializeConfig(hash);
          if (deserialized) return { ...base, ...deserialized };
        } else {
          return { ...base, ...JSON.parse(decodeURIComponent(hash)) };
        }
      }
    } catch (e) {}
    return base;
  });

  const result = useMemo(() => calculateLayout(config), [config]);

  useEffect(() => {
    localStorage.setItem('app_lang', lang);
  }, [lang]);

  useEffect(() => {
    if (config.distributionMode === 'by-gap' && 
        config.elementType !== 'calculated' && 
        result.elementCount !== config.elementCount) {
      setConfig(prev => ({ ...prev, elementCount: result.elementCount }));
      return;
    }

    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(config));
      const encodedConfig = serializeConfig(config);
      const newHash = `#${encodedConfig}`;
      if (window.location.hash !== newHash) {
        window.history.replaceState(null, '', newHash);
      }
    } catch (e) {}
  }, [config, result.elementCount]);

  const updateConfig = (updates: Partial<AppConfig>) => {
    setConfig(prev => {
      const next = { ...prev, ...updates };
      if (updates.maxEndGap !== undefined && updates.isMaxEndGapLocked === undefined) {
        next.isMaxEndGapLocked = false;
      }
      return next;
    });
  };

  const deriveWidth = (S: number, G: number, N: number) => {
    if (N <= 0) return 0;
    const W = (S - (N + 1) * G) / N;
    return Math.max(0, Math.round(W));
  };

  const handleTargetGapChange = (value: number) => {
    if (config.elementType === 'calculated') {
      const newWidth = deriveWidth(result.edgeToEdge, value, config.elementCount);
      updateConfig({ targetGap: value, boardWidth: newWidth });
    } else {
      updateConfig({ targetGap: value, distributionMode: 'by-gap' });
    }
  };

  const handleElementCountChange = (value: number) => {
    const newCount = Math.max(0, value);
    if (config.elementType === 'calculated') {
      const newWidth = deriveWidth(result.edgeToEdge, config.targetGap, newCount);
      updateConfig({ elementCount: newCount, boardWidth: newWidth });
    } else {
      const tempConfig = { ...config, elementCount: newCount, distributionMode: 'by-count' as const };
      const tempResult = calculateLayout(tempConfig);
      updateConfig({
        elementCount: newCount,
        distributionMode: 'by-count',
        targetGap: Math.round(tempResult.actualGap)
      });
    }
  };

  const handleAdjustCount = (delta: number) => {
    handleElementCountChange(result.elementCount + delta);
  };

  const handleElementTypeChange = (type: ElementType) => {
    if (type === 'calculated') {
      const newWidth = deriveWidth(result.edgeToEdge, config.targetGap, result.elementCount);
      updateConfig({ elementType: type, boardWidth: newWidth, distributionMode: 'by-count', elementCount: result.elementCount });
    } else {
      updateConfig({ elementType: type });
    }
  };

  const handleToggleMaxEndGapLock = () => {
    const isNowLocked = !config.isMaxEndGapLocked;
    if (isNowLocked) {
      updateConfig({ 
        isMaxEndGapLocked: true, 
        maxEndGap: config.targetGap 
      });
    } else {
      updateConfig({ isMaxEndGapLocked: false });
    }
  };

  const handleExportImage = async () => {
    const element = document.getElementById('export-container');
    if (!element) return;
    setIsExporting(true);
    try {
      await new Promise(r => setTimeout(r, 200));
      const canvas = await (window as any).html2canvas(element, { scale: 2, backgroundColor: '#f8fafc', logging: false, useCORS: true });
      const image = canvas.toDataURL("image/png");
      const link = document.createElement('a');
      link.href = image;
      link.download = `layout-${Date.now()}.png`;
      link.click();
    } catch (error) {
      console.error('Export failed:', error);
      alert(lang === 'ru' ? 'Ошибка при создании изображения.' : 'Export failed.');
    } finally { setIsExporting(false); }
  };

  const handleShare = () => {
    navigator.clipboard.writeText(window.location.href);
    alert(lang === 'ru' ? 'Ссылка скопирована!' : 'Link copied!');
  };

  const inputClasses = "w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all";
  const labelClasses = "block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1";

  // --- UI ---
  return (
    <div className="max-w-4xl mx-auto p-4 md:p-6 space-y-6 pb-20">
      <div className="flex justify-between items-center">
        <div className="flex items-center gap-3">
          <div className="bg-blue-600 p-2 rounded-xl shadow-lg shadow-blue-200">
            <LayoutGrid className="w-6 h-6 text-white" />
          </div>
          <h1 className="text-2xl font-black text-slate-900 tracking-tight uppercase">{t.title}</h1>
        </div>
        <button 
          onClick={() => setLang(lang === 'ru' ? 'en' : 'ru')}
          className="flex items-center gap-2 px-3 py-2 bg-white border border-slate-200 rounded-lg text-xs font-bold text-slate-600 hover:bg-slate-50 transition-colors"
        >
          <Languages className="w-4 h-4" />
          {lang === 'ru' ? 'English' : 'Русский'}
        </button>
      </div>

      <div id="export-container" className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 space-y-6">
            <div className="flex items-center gap-2 mb-2">
              <Settings2 className="w-4 h-4 text-blue-600" />
              <h2 className="text-sm font-black text-slate-900 uppercase tracking-widest">{t.platform}</h2>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className={labelClasses}>{t.distance}</label>
                <div className="relative">
                  <input 
                    type="number" 
                    value={config.distanceValue} 
                    onChange={e => updateConfig({ distanceValue: Number(e.target.value) })}
                    className={inputClasses} 
                  />
                  <span className="absolute right-3 top-2 text-xs font-bold text-slate-400">мм</span>
                </div>
              </div>
              <div>
                <label className={labelClasses}>Mode</label>
                <div className="flex bg-slate-100 p-1 rounded-lg">
                  <button 
                    onClick={() => updateConfig({ distanceMode: 'center-to-center' })}
                    className={`flex-1 py-1 text-[10px] font-bold rounded-md transition-all ${config.distanceMode === 'center-to-center' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-500'}`}
                  >
                    {t.axes}
                  </button>
                  <button 
                    onClick={() => updateConfig({ distanceMode: 'edge-to-edge' })}
                    className={`flex-1 py-1 text-[10px] font-bold rounded-md transition-all ${config.distanceMode === 'edge-to-edge' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-500'}`}
                  >
                    {t.edges}
                  </button>
                </div>
              </div>
            </div>

            <div className="space-y-4">
              <div>
                <label className={labelClasses}>{t.elementType}</label>
                <div className="grid grid-cols-3 gap-2">
                  <button 
                    onClick={() => handleElementTypeChange('point')}
                    className={`flex flex-col items-center gap-1 p-3 border rounded-xl transition-all ${config.elementType === 'point' ? 'bg-blue-50 border-blue-200 text-blue-600' : 'bg-white border-slate-200 text-slate-500'}`}
                  >
                    <Circle className="w-5 h-5" />
                    <span className="text-[10px] font-bold">{t.point}</span>
                  </button>
                  <button 
                    onClick={() => handleElementTypeChange('board')}
                    className={`flex flex-col items-center gap-1 p-3 border rounded-xl transition-all ${config.elementType === 'board' ? 'bg-blue-50 border-blue-200 text-blue-600' : 'bg-white border-slate-200 text-slate-500'}`}
                  >
                    <Box className="w-5 h-5" />
                    <span className="text-[10px] font-bold">{t.segment}</span>
                  </button>
                  <button 
                    onClick={() => handleElementTypeChange('calculated')}
                    className={`flex flex-col items-center gap-1 p-3 border rounded-xl transition-all ${config.elementType === 'calculated' ? 'bg-blue-50 border-blue-200 text-blue-600' : 'bg-white border-slate-200 text-slate-500'}`}
                  >
                    <Maximize2 className="w-5 h-5" />
                    <span className="text-[10px] font-bold">{t.calculate}</span>
                  </button>
                </div>
              </div>

              {config.elementType === 'board' && (
                <div>
                  <label className={labelClasses}>{t.segmentWidth}</label>
                  <input 
                    type="number" 
                    value={config.boardWidth} 
                    onChange={e => updateConfig({ boardWidth: Number(e.target.value) })}
                    className={inputClasses} 
                  />
                </div>
              )}

              {config.elementType === 'calculated' && (
                <div className="p-3 bg-blue-50 border border-blue-100 rounded-xl">
                  <p className="text-[10px] font-bold text-blue-700 uppercase mb-1">{t.calcWidth}</p>
                  <p className="text-lg font-black text-blue-900">{result.elementPositions.length > 0 ? formatMm(config.boardWidth) : 0} {t.mm}</p>
                  <p className="text-[9px] text-blue-600 mt-1">{t.widthAuto}</p>
                </div>
              )}
            </div>

            <div className="pt-4 border-t border-slate-100 space-y-4">
              <div className="flex justify-between items-end">
                <div className="flex-1 mr-4">
                  <label className={labelClasses}>{t.targetGap}</label>
                  <input 
                    type="number" 
                    value={config.targetGap} 
                    onChange={e => handleTargetGapChange(Number(e.target.value))}
                    className={inputClasses} 
                  />
                </div>
                <div className="flex-1">
                  <label className={labelClasses}>{t.elementCount}</label>
                  <div className="flex items-center gap-2">
                    <button onClick={() => handleAdjustCount(-1)} className="p-2 bg-slate-100 rounded-lg hover:bg-slate-200 transition-colors"><Minus className="w-4 h-4" /></button>
                    <input 
                      type="number" 
                      value={config.elementCount} 
                      onChange={e => handleElementCountChange(Number(e.target.value))}
                      className={`${inputClasses} text-center`} 
                    />
                    <button onClick={() => handleAdjustCount(1)} className="p-2 bg-slate-100 rounded-lg hover:bg-slate-200 transition-colors"><Plus className="w-4 h-4" /></button>
                  </div>
                </div>
              </div>

              {config.elementType !== 'calculated' && (
                <div>
                  <div className="flex items-center justify-between mb-1">
                    <label className={labelClasses}>{t.maxEndGap}</label>
                    <button 
                      onClick={handleToggleMaxEndGapLock}
                      className={`flex items-center gap-1 text-[9px] font-black uppercase tracking-tighter transition-colors ${config.isMaxEndGapLocked ? 'text-blue-600' : 'text-slate-400'}`}
                    >
                      {config.isMaxEndGapLocked ? <Lock className="w-3 h-3" /> : <Unlock className="w-3 h-3" />}
                      {t.syncTarget}
                    </button>
                  </div>
                  <input 
                    type="number" 
                    disabled={config.isMaxEndGapLocked}
                    value={config.maxEndGap} 
                    onChange={e => updateConfig({ maxEndGap: Number(e.target.value) })}
                    className={`${inputClasses} ${config.isMaxEndGapLocked ? 'bg-slate-50 text-slate-400 cursor-not-allowed' : ''}`} 
                  />
                  {config.isMaxEndGapLocked && <p className="text-[9px] font-bold text-blue-500 mt-1 uppercase">{t.syncActive}</p>}
                </div>
              )}
            </div>
          </div>

          <div className="space-y-6">
            <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
              <h2 className="text-sm font-black text-slate-900 uppercase tracking-widest mb-4">{t.calcResults}</h2>
              <div className="grid grid-cols-2 gap-4">
                <div className="bg-slate-50 p-4 rounded-xl border border-slate-100">
                  <p className={labelClasses}>{t.platformDist}</p>
                  <p className="text-xl font-black text-slate-900">{formatMm(result.edgeToEdge)} <span className="text-xs text-slate-400 uppercase">{t.mm}</span></p>
                </div>
                <div className="bg-slate-50 p-4 rounded-xl border border-slate-100">
                  <p className={labelClasses}>{t.elements}</p>
                  <p className="text-xl font-black text-slate-900">{result.elementCount} <span className="text-xs text-slate-400 uppercase">{t.pcs}</span></p>
                </div>
                <div className="bg-red-50 p-4 rounded-xl border border-red-100">
                  <p className={`${labelClasses} text-red-400`}>{t.stepBetween}</p>
                  <p className="text-xl font-black text-red-900">{formatMm(result.actualGap)} <span className="text-xs text-red-400 uppercase">{t.mm}</span></p>
                </div>
                <div className="bg-blue-50 p-4 rounded-xl border border-blue-100">
                  <p className={`${labelClasses} text-blue-400`}>{t.firstOffset}</p>
                  <p className="text-xl font-black text-blue-900">{formatMm(result.firstElementOffset)} <span className="text-xs text-blue-400 uppercase">{t.mm}</span></p>
                </div>
              </div>

              {result.warnings.length > 0 && (
                <div className="mt-4 p-3 bg-amber-50 border border-amber-200 rounded-xl space-y-1">
                  {result.warnings.map((w, i) => (
                    <div key={i} className="flex items-start gap-2 text-amber-700">
                      <AlertTriangle className="w-4 h-4 shrink-0 mt-0.5" />
                      <p className="text-[11px] font-bold leading-tight">{w}</p>
                    </div>
                  ))}
                </div>
              )}
            </div>

            <div className="flex gap-3">
              <button 
                onClick={handleShare}
                className="flex-1 flex items-center justify-center gap-2 bg-white border border-slate-200 text-slate-700 font-bold py-3 rounded-xl hover:bg-slate-50 transition-all active:scale-[0.98]"
              >
                <Share2 className="w-4 h-4" />
                {t.link}
              </button>
              <button 
                onClick={handleExportImage}
                disabled={isExporting}
                className="flex-1 flex items-center justify-center gap-2 bg-slate-900 text-white font-bold py-3 rounded-xl hover:bg-slate-800 transition-all active:scale-[0.98] disabled:opacity-50"
              >
                {isExporting ? <span className="animate-pulse">{t.creating}</span> : <><ImageIcon className="w-4 h-4" /> {t.toImage}</>}
              </button>
            </div>
          </div>
        </div>

        <MainDiagram config={config} result={result} lang={lang} />
        <ConstructionRuler config={config} result={result} lang={lang} />
      </div>
    </div>
  );
};

export default App;

import React from 'react';
import { AppConfig, CalculationResult } from '../types';
import { formatMm } from '../utils/calculations';

interface MainDiagramProps {
  config: AppConfig;
  result: CalculationResult;
  lang: 'ru' | 'en';
}

const LABELS = {
  ru: {
    step: 'Шаг',
    offset: 'Отступ',
    width: 'Ширина',
    total: 'Всего',
    diagram: 'Схема'
  },
  en: {
    step: 'Step',
    offset: 'Offset',
    width: 'Width',
    total: 'Total',
    diagram: 'Diagram'
  }
};

export const MainDiagram: React.FC<MainDiagramProps> = ({ config, result, lang }) => {
  const { elementType, boardWidth } = config;
  const { edgeToEdge, elementPositions, firstElementOffset, actualGap } = result;
  const t = LABELS[lang];

  // --- SVG КООРДИНАТЫ (0-1000 x 0-500) ---
  const viewWidth = 1000;
  const viewHeight = 500;
  const centerY = 250;

  const sideMargin = 80;
  const platformWidth = 50; 

  const startX = sideMargin + platformWidth; 
  const endX = viewWidth - sideMargin - platformWidth; 

  const usableWidth = endX - startX;
  const scale = edgeToEdge > 0 ? usableWidth / edgeToEdge : 1;

  const platformVisualHeight = 120;
  const elemVisualHeight = 50;
  const platformTop = centerY - platformVisualHeight / 2;
  const platformBottom = centerY + platformVisualHeight / 2;
  const elemTop = centerY - elemVisualHeight / 2;

  const renderDimension = (x1: number, x2: number, y: number, label: string, color: string = "#64748b", isBelow = false) => {
    const midX = (x1 + x2) / 2;
    const textYOffset = isBelow ? 28 : -15;

    return (
      <g>
        <line x1={x1} y1={y} x2={x2} y2={y} stroke={color} strokeWidth="2" />
        <line x1={x1} y1={y - 10} x2={x1} y2={y + 10} stroke={color} strokeWidth="2" />
        <line x1={x2} y1={y - 10} x2={x2} y2={y + 10} stroke={color} strokeWidth="2" />
        <text 
          x={midX} 
          y={y + textYOffset} 
          textAnchor="middle" 
          className="font-bold" 
          fill={color}
          style={{ 
            fontSize: '16px', 
            paintOrder: 'stroke', 
            stroke: 'white', 
            strokeWidth: '4px'
          }}
        >
          {label}
        </text>
      </g>
    );
  };

  const hasWidth = elementType !== 'point';
  const yStep = 90;
  const yOffset = 165;
  const yWidth = 335;
  const yTotal = 410;

  return (
    <div className="w-full bg-white rounded-xl shadow-sm border border-slate-200 p-4 relative overflow-hidden">
      <div className="flex justify-between items-start mb-4">
        <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{t.diagram} (мм)</h3>
      </div>

      <div className="w-full overflow-hidden">
        <svg 
          viewBox={`0 0 ${viewWidth} ${viewHeight}`} 
          className="w-full h-auto" 
          style={{ display: 'block', maxWidth: '100%' }}
        >
          {/* Базовая ось */}
          <line x1={0} y1={centerY} x2={viewWidth} y2={centerY} stroke="#f1f5f9" strokeWidth="1" strokeDasharray="10,5" />

          {/* Левая платформа */}
          <path 
            d={`M ${startX - platformWidth},${platformTop} 
               L ${startX - platformWidth},${platformBottom} 
               A ${platformWidth},${platformVisualHeight/2} 0 0 0 ${startX},${centerY}
               A ${platformWidth},${platformVisualHeight/2} 0 0 0 ${startX - platformWidth},${platformTop} Z`} 
            fill="#f8fafc" 
            stroke="#94a3b8" 
            strokeWidth="3" 
          />

          {/* Правая платформа */}
          <path 
            d={`M ${endX + platformWidth},${platformTop} 
               L ${endX + platformWidth},${platformBottom} 
               A ${platformWidth},${platformVisualHeight/2} 0 0 1 ${endX},${centerY}
               A ${platformWidth},${platformVisualHeight/2} 0 0 1 ${endX + platformWidth},${platformTop} Z`} 
            fill="#f8fafc" 
            stroke="#94a3b8" 
            strokeWidth="3" 
          />

          {/* Центральная линия */}
          <line x1={startX} y1={centerY} x2={endX} y2={centerY} stroke="#0f172a" strokeWidth="1" strokeDasharray="8,4" />

          {/* Элементы разметки */}
          {elementPositions.map((pos, idx) => {
            const x = startX + (pos * scale);
            if (elementType === 'point') {
              return <circle key={idx} cx={x} cy={centerY} r="10" fill="#ef4444" stroke="white" strokeWidth="3" />;
            } else {
              const width = boardWidth * scale;
              return <rect key={idx} x={x} y={elemTop} width={width} height={elemVisualHeight} fill="#ef4444" rx="3" stroke="white" strokeWidth="2" />;
            }
          })}

          {/* Размеры */}
          <g>
            {elementPositions.length > 1 && renderDimension(
              startX + (firstElementOffset + (hasWidth ? boardWidth : 0)) * scale,
              startX + (firstElementOffset + (hasWidth ? boardWidth : 0) + actualGap) * scale,
              yStep, 
              `${t.step}: ${formatMm(actualGap)}`,
              "#dc2626"
            )}

            {renderDimension(
              startX, 
              startX + (firstElementOffset * scale), 
              yOffset, 
              `${t.offset}: ${formatMm(firstElementOffset)}`,
              "#2563eb"
            )}

            {hasWidth && elementPositions.length > 0 && renderDimension(
              startX + (firstElementOffset * scale),
              startX + ((firstElementOffset + boardWidth) * scale),
              yWidth,
              `${t.width}: ${formatMm(boardWidth)}`,
              "#7c3aed",
              true
            )}

            {renderDimension(
              startX, 
              endX, 
              yTotal, 
              `${t.total}: ${formatMm(edgeToEdge)} мм`,
              "#0f172a",
              true
            )}
          </g>
        </svg>
      </div>
    </div>
  );
};

