                    <Maximize2 className="w-3 h-3 text-blue-500" /> {t.maxEndGap}
                  </h2>
                  <button 
                    onClick={() => updateConfig({ maxEndGap: 300 })}
                    className="text-base hover:scale-125 transition-transform active:scale-90 p-0.5 leading-none"
