const App: React.FC = () => {
  const [lang, setLang] = useState<'ru' | 'en'>(() => {
    const saved = localStorage.getItem('app_lang');
    return (saved === 'en' || saved === 'ru') ? saved : 'ru';
  });

  const t = TRANSLATIONS[lang];
  const [isExporting, setIsExporting] = useState(false);

  const [config, setConfig] = useState<AppConfig>(() => {
    let base = INITIAL_STATE;
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) base = { ...base, ...JSON.parse(saved) };
    } catch (e) {}

    try {
      const hash = window.location.hash.substring(1);
      if (hash) {
        if (hash.startsWith('v2_') || hash.startsWith('v3_')) {
          const deserialized = deserializeConfig(hash);
          if (deserialized) return { ...base, ...deserialized };
        } else {
          return { ...base, ...JSON.parse(decodeURIComponent(hash)) };
        }
      }
    } catch (e) {}
    return base;
  });

  const result = useMemo(() => calculateLayout(config), [config]);

  useEffect(() => {
    localStorage.setItem('app_lang', lang);
  }, [lang]);

  useEffect(() => {
    if (config.distributionMode === 'by-gap' && 
        config.elementType !== 'calculated' && 
        result.elementCount !== config.elementCount) {
      setConfig(prev => ({ ...prev, elementCount: result.elementCount }));
      return;
    }

    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(config));
      const encodedConfig = serializeConfig(config);
      const newHash = `#${encodedConfig}`;
      if (window.location.hash !== newHash) {
        window.history.replaceState(null, '', newHash);
      }
    } catch (e) {}
  }, [config, result.elementCount]);

  const updateConfig = (updates: Partial<AppConfig>) => {
    setConfig(prev => {
      const next = { ...prev, ...updates };
      if (updates.maxEndGap !== undefined && updates.isMaxEndGapLocked === undefined) {
        next.isMaxEndGapLocked = false;
      }
      return next;
    });
  };

  const deriveWidth = (S: number, G: number, N: number) => {
    if (N <= 0) return 0;
    const W = (S - (N + 1) * G) / N;
    return Math.max(0, Math.round(W));
  };

  const handleTargetGapChange = (value: number) => {
    if (config.elementType === 'calculated') {
      const newWidth = deriveWidth(result.edgeToEdge, value, config.elementCount);
      updateConfig({ targetGap: value, boardWidth: newWidth });
    } else {
      updateConfig({ targetGap: value, distributionMode: 'by-gap' });
    }
  };

  const handleElementCountChange = (value: number) => {
    const newCount = Math.max(0, value);
    if (config.elementType === 'calculated') {
      const newWidth = deriveWidth(result.edgeToEdge, config.targetGap, newCount);
      updateConfig({ elementCount: newCount, boardWidth: newWidth });
    } else {
      const tempConfig = { ...config, elementCount: newCount, distributionMode: 'by-count' as const };
      const tempResult = calculateLayout(tempConfig);
      updateConfig({
        elementCount: newCount,
        distributionMode: 'by-count',
        targetGap: Math.round(tempResult.actualGap)
      });
    }
  };

  const handleAdjustCount = (delta: number) => {
    handleElementCountChange(result.elementCount + delta);
  };

  const handleElementTypeChange = (type: ElementType) => {
    if (type === 'calculated') {
      const newWidth = deriveWidth(result.edgeToEdge, config.targetGap, result.elementCount);
      updateConfig({ elementType: type, boardWidth: newWidth, distributionMode: 'by-count', elementCount: result.elementCount });
    } else {
      updateConfig({ elementType: type });
    }
  };

  const handleToggleMaxEndGapLock = () => {
    const isNowLocked = !config.isMaxEndGapLocked;
    if (isNowLocked) {
      updateConfig({ 
        isMaxEndGapLocked: true, 
        maxEndGap: config.targetGap 
      });
    } else {
      updateConfig({ isMaxEndGapLocked: false });
    }
  };

  const handleExportImage = async () => {
    const element = document.getElementById('export-container');
    if (!element) return;
    setIsExporting(true);
    try {
      await new Promise(r => setTimeout(r, 200));
      const canvas = await (window as any).html2canvas(element, { scale: 2, backgroundColor: '#f8fafc', logging: false, useCORS: true });
      const image = canvas.toDataURL("image/png");
      const link = document.createElement('a');
      link.href = image;
      link.download = `layout-${Date.now()}.png`;
      link.click();
    } catch (error) {
      console.error('Export failed:', error);
    } finally { setIsExporting(false); }
  };

  const handleShare = () => {
    navigator.clipboard.writeText(window.location.href);
    alert(lang === 'ru' ? 'Ссылка скопирована!' : 'Link copied!');
  };

  // Стили для инпутов: черный жирный текст, светлый фон
  const inputContainerClasses = "relative bg-slate-100 border border-slate-300 rounded-xl overflow-hidden shadow-sm focus-within:ring-2 focus-within:ring-blue-500/20 focus-within:border-blue-500 transition-all";
  const inputBaseClasses = "w-full bg-transparent px-3 py-2.5 text-base font-black text-slate-900 outline-none";
  const labelClasses = "block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1.5 ml-1";

  return (
    <div className="min-h-screen pb-20 sm:pb-8 bg-slate-50 font-sans">
      <main className="max-w-6xl mx-auto px-4 py-6">
        {/* Header */}
        <div className="flex items-center justify-between mb-8">
          <div className="flex items-center gap-3">
            <div className="bg-blue-600 p-2.5 rounded-2xl shadow-xl shadow-blue-200">
              <Ruler className="w-6 h-6 text-white" />
            </div>
            <h1 className="text-xl font-black text-slate-800 uppercase tracking-tight">{t.title}</h1>
          </div>
          <button 
            onClick={() => setLang(lang === 'ru' ? 'en' : 'ru')}
            className="flex items-center gap-2 px-3 py-2 bg-white border border-slate-200 rounded-xl text-[10px] font-black text-slate-500 hover:bg-slate-50 transition-colors uppercase"
          >
            <Languages className="w-3.5 h-3.5" />
            {lang === 'ru' ? 'RU / EN' : 'EN / RU'}
          </button>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
          {/* Settings Column */}
          <div className="lg:col-span-5 space-y-6 no-print">
            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-200">
              <div className="flex items-center gap-2 mb-6">
                <Settings2 className="w-5 h-5 text-blue-600" />
                <h2 className="text-sm font-black text-slate-800 uppercase tracking-widest">{t.settings}</h2>
              </div>

              <div className="space-y-6">
                {/* Platform Diameter Selection */}
                <div>
                  <label className={labelClasses}>{t.platform} (Ø)</label>
                  <div className="grid grid-cols-3 gap-2">
                    {[1200, 1500, 1800].map(d => (
                      <button 
                        key={d} 
                        onClick={() => updateConfig({ diameter: d })} 
                        className={`py-3 rounded-xl border-2 text-xs font-black transition-all ${config.diameter === d ? 'bg-blue-600 border-blue-600 text-white shadow-lg shadow-blue-100' : 'bg-slate-50 border-transparent text-slate-500 hover:bg-slate-100'}`}
                      >
                        {d}
                      </button>
                    ))}
                  </div>
                </div>

                {/* Distance & Mode */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className={labelClasses}>{t.distance}</label>
                    <div className={inputContainerClasses}>
                      <input 
                        type="number" 
                        value={config.distanceValue} 
                        onChange={(e) => updateConfig({ distanceValue: Number(e.target.value) })} 
                        className={inputBaseClasses} 
                      />
                      <span className="absolute right-3 top-3 text-[10px] font-black text-slate-400 uppercase">мм</span>
                    </div>
                  </div>
                  <div>
                    <label className={labelClasses}>Режим</label>
                    <div className="flex p-1 bg-slate-100 rounded-xl h-[46px]">
                      <button onClick={() => updateConfig({ distanceMode: 'center-to-center' })} className={`flex-1 py-1 rounded-lg text-[10px] font-black transition-all uppercase ${config.distanceMode === 'center-to-center' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-500'}`}>{t.axes}</button>
                      <button onClick={() => updateConfig({ distanceMode: 'edge-to-edge' })} className={`flex-1 py-1 rounded-lg text-[10px] font-black transition-all uppercase ${config.distanceMode === 'edge-to-edge' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-500'}`}>{t.edges}</button>
                    </div>
                  </div>
                </div>

                {/* Element Type Selection - Icons only as requested */}
                <div>
                  <label className={labelClasses}>{t.elementType}</label>
                  <div className="flex bg-slate-100 p-1.5 rounded-2xl gap-2">
                    {[
                      { id: 'point', icon: Circle },
                      { id: 'board', icon: Box },
                      { id: 'calculated', icon: Maximize2 }
                    ].map(({ id, icon: Icon }) => (
                      <button 
                        key={id} 
                        onClick={() => handleElementTypeChange(id as ElementType)}
                        className={`flex-1 flex items-center justify-center py-4 rounded-xl transition-all ${config.elementType === id ? 'bg-white shadow-md text-blue-600 scale-105' : 'text-slate-400 hover:text-slate-600'}`}
                        title={t[id as keyof typeof t]}
                      >
                        <Icon className="w-6 h-6" />
                      </button>
                    ))}
                  </div>
                  {config.elementType === 'calculated' && (
                    <div className="mt-2 px-2">
                       <p className="text-[10px] font-bold text-blue-500 uppercase flex items-center gap-1.5"><Maximize2 className="w-3 h-3"/> {t.widthAuto}: <span className="text-blue-700">{formatMm(config.boardWidth)} {t.mm}</span></p>
                    </div>
                  )}
                  {config.elementType === 'board' && (
                    <div className="mt-3">
                      <label className={labelClasses}>{t.segmentWidth}</label>
                      <div className={inputContainerClasses}>
                        <input 
                          type="number" 
                          value={config.boardWidth} 
                          onChange={(e) => updateConfig({ boardWidth: Number(e.target.value) })} 
                          className={inputBaseClasses} 
                        />
                      </div>
                    </div>
                  )}
                </div>

                {/* Distribution: Gap and Count */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className={labelClasses}>{t.targetGap}</label>
                    <div className={inputContainerClasses}>
                      <input 
                        type="number" 
                        value={config.targetGap} 
                        onChange={(e) => handleTargetGapChange(Number(e.target.value))} 
                        className={inputBaseClasses} 
                      />
                    </div>
                  </div>
                  <div>
                    <label className={labelClasses}>{t.elementCount}</label>
                    <div className="flex gap-2">
                      <div className={`${inputContainerClasses} flex-1 flex items-center`}>
                        <button onClick={() => handleAdjustCount(-1)} className="px-3 py-2 text-slate-500 hover:text-blue-600 transition-colors"><Minus className="w-4 h-4" /></button>
                        <input 
                          type="number" 
                          value={config.elementCount} 
                          onChange={(e) => handleElementCountChange(Number(e.target.value))} 
                          className="w-full bg-transparent text-center text-base font-black text-slate-900 outline-none" 
                        />
                        <button onClick={() => handleAdjustCount(1)} className="px-3 py-2 text-slate-500 hover:text-blue-600 transition-colors"><Plus className="w-4 h-4" /></button>
                      </div>
                    </div>
                  </div>
                </div>

                {/* Max End Gap with Tractor */}
                <div className="pt-2">
                  <div className="flex items-center justify-between mb-2">
                    <div className="flex items-center gap-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{t.maxEndGap}</label>
                      <button 
                        onClick={() => updateConfig({ maxEndGap: 300 })}
                        className="text-lg hover:scale-125 transition-transform active:scale-90 p-1 bg-amber-50 rounded-lg shadow-sm border border-amber-100 leading-none"
                        title="300mm"
                      >
                        🚜
                      </button>
                    </div>
                    <button 
                      onClick={handleToggleMaxEndGapLock} 
                      className={`text-[9px] font-black uppercase px-2 py-1 rounded-lg transition-all flex items-center gap-1.5 ${config.isMaxEndGapLocked ? 'bg-blue-600 text-white shadow-md' : 'bg-slate-100 text-slate-400 hover:bg-slate-200'}`}
                    >
                      {config.isMaxEndGapLocked ? <Lock className="w-2.5 h-2.5" /> : <Unlock className="w-2.5 h-2.5" />}
                      {t.syncTarget}
                    </button>
                  </div>
                  <div className={`${inputContainerClasses} ${config.isMaxEndGapLocked ? 'bg-blue-50/50' : ''}`}>
                    <input 
                      type="number" 
                      value={config.isMaxEndGapLocked ? config.targetGap : config.maxEndGap} 
                      onChange={(e) => updateConfig({ maxEndGap: Number(e.target.value) })} 
                      disabled={config.isMaxEndGapLocked}
                      className={`${inputBaseClasses} ${config.isMaxEndGapLocked ? 'text-blue-600' : ''}`} 
                    />
                  </div>
                </div>
              </div>
            </div>

            {/* Actions */}
            <div className="grid grid-cols-2 gap-3">
              <button 
                onClick={handleShare} 
                className="flex items-center justify-center gap-2 px-4 py-4 bg-white border border-slate-200 text-slate-600 rounded-2xl text-xs font-black uppercase shadow-sm hover:bg-slate-50 transition-all active:scale-95"
              >
                <Share2 className="w-4 h-4" />
                {t.link}
              </button>
              <button 
                onClick={handleExportImage} 
                disabled={isExporting} 
                className={`flex items-center justify-center gap-2 px-4 py-4 rounded-2xl text-xs font-black uppercase shadow-lg transition-all active:scale-95 ${isExporting ? 'bg-slate-400 text-white' : 'bg-slate-900 text-white hover:bg-slate-800 shadow-slate-200'}`}
              >
                <ImageIcon className="w-4 h-4" />
                {isExporting ? t.creating : t.toImage}
              </button>
            </div>
          </div>

          {/* Results Column */}
          <div className="lg:col-span-7 space-y-6" id="export-container">
            {/* Results Grid */}
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
               <StatBox label={t.platformDist} value={`${Math.round(result.edgeToEdge)}`} unit={t.mm} />
               <StatBox label={t.elements} value={`${result.elementCount}`} unit={t.pcs} />
               <StatBox label={t.betweenElements} value={`${Math.round(result.actualGap)}`} unit={t.mm} highlight />
               <StatBox label={t.firstOffset} value={`${Math.round(result.firstElementOffset)}`} unit={t.mm} />
            </div>

            {/* Warnings */}
            {result.warnings.length > 0 && (
              <div className="bg-amber-50 border border-amber-200 rounded-2xl p-4 shadow-sm flex gap-4 no-print animate-in fade-in slide-in-from-top-4 duration-300">
                <div className="bg-amber-100 p-1.5 rounded-lg h-fit"><AlertTriangle className="w-5 h-5 text-amber-600 shrink-0" /></div>
                <div className="text-[11px] text-amber-900 font-bold uppercase leading-relaxed tracking-tight">
                  {result.warnings.map((w, idx) => <div key={idx} className="mb-0.5">• {w}</div>)}
                </div>
              </div>
            )}

            <div className="space-y-6">
              <MainDiagram config={config} result={result} lang={lang} />
              <ConstructionRuler config={config} result={result} lang={lang} />
            </div>
          </div>
        </div>
      </main>

      {/* Mobile Sticky Summary */}
      <div className="fixed bottom-0 left-0 right-0 bg-white/80 backdrop-blur-md border-t border-slate-200 p-4 sm:hidden flex justify-between items-center z-50 no-print shadow-[0_-8px_30px_rgba(0,0,0,0.05)]">
         <div className="flex flex-col">
            <span className="text-[10px] text-slate-400 font-black uppercase tracking-tight">{t.stepBetween}</span>
            <span className="text-xl font-black text-blue-600 leading-none">{Math.round(result.actualGap)} {t.mm}</span>
         </div>
         <button 
          onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })} 
          className="bg-blue-600 text-white p-3.5 rounded-2xl shadow-xl shadow-blue-200 active:scale-90 transition-transform"
         >
          <Settings2 className="w-5 h-5" />
         </button>
      </div>
    </div>
  );
};

const StatBox = ({ label, value, unit, highlight = false }: { label: string, value: string, unit?: string, highlight?: boolean }) => (
  <div className={`bg-white p-4 rounded-2xl shadow-sm border ${highlight ? 'border-blue-200 bg-blue-50/30' : 'border-slate-200'} text-center transition-all`}>
    <p className="text-[9px] font-black text-slate-400 uppercase mb-1 tracking-widest">{label}</p>
    <div className="flex items-baseline justify-center gap-0.5">
      <span className={`text-lg font-black ${highlight ? 'text-blue-600' : 'text-slate-800'}`}>{value}</span>
      <span className="text-[10px] font-bold text-slate-400 uppercase">{unit}</span>
    </div>
  </div>
);

export default App;

