export type ElementType = 'point' | 'board' | 'calculated';
export type DistanceMode = 'center-to-center' | 'edge-to-edge';
export type DistributionMode = 'by-gap' | 'by-count';
export type RulerMarkMode = 'center' | 'edge';

export interface AppConfig {
  diameter: number;
  distanceMode: DistanceMode;
  distanceValue: number;
  elementType: ElementType;
  boardWidth: number;
  distributionMode: DistributionMode;
  targetGap: number;
  elementCount: number;
  maxEndGap: number;
  isMaxEndGapLocked: boolean; // Синхронизация с желаемым отступом
  isFirstOffsetFixed: boolean; // Режим фиксированного отступа (не максимального)
  rulerMarkMode: RulerMarkMode;
}

export interface CalculationResult {
  edgeToEdge: number;
  centerToCenter: number;
  actualGap: number;
  elementCount: number;
  firstElementOffset: number;
  warnings: string[];
  elementPositions: number[]; // relative to the inner edge of the first circle
}

import { AppConfig, CalculationResult } from '../types';

export const calculateLayout = (config: AppConfig): CalculationResult => {
  const {
    diameter,
    distanceMode,
    distanceValue,
    elementType,
    boardWidth,
    distributionMode,
    targetGap,
    elementCount: manualCount,
    maxEndGap,
    isMaxEndGapLocked,
    isFirstOffsetFixed
  } = config;

  const D = diameter;
  const V = distanceValue;
  const W = elementType === 'point' ? 0 : boardWidth;
  const M = maxEndGap;

  let S: number; // Edge-to-edge distance
  let L: number; // Center-to-center distance

  if (distanceMode === 'center-to-center') {
    L = V;
    S = L - D;
  } else {
    S = V;
    L = S + D;
  }

  const warnings: string[] = [];
  if (S < 0) warnings.push('Дистанция слишком мала');

  let N = manualCount;

  if (distributionMode === 'by-gap' && S > 0 && elementType !== 'calculated') {
    const effectiveEdge = isMaxEndGapLocked ? targetGap : Math.min(M, targetGap);
    const nIdeal = (S - 2 * effectiveEdge + targetGap) / (targetGap + W);
    N = Math.max(1, Math.round(nIdeal));
  }

  let actualG_edge = 0;
  let actualG_inner = 0;

  if (S > 0 && N > 0) {
    const Gu = (S - N * W) / (N + 1);

    if (elementType === 'calculated') {
      actualG_edge = targetGap;
      actualG_inner = targetGap;
    } else if (isFirstOffsetFixed) {
      // Режим фиксированного отступа: первый отступ всегда равен M
      actualG_edge = M;
      if (N > 1) {
        actualG_inner = (S - 2 * M - N * W) / (N - 1);
      } else {
        // Если только один элемент, ставим его по центру, игнорируя фиксацию, если она невозможна
        actualG_edge = (S - W) / 2;
        actualG_inner = 0;
      }
    } else if (isMaxEndGapLocked || Gu <= M + 0.1) {
      actualG_edge = Gu;
      actualG_inner = Gu;
    } else {
      actualG_edge = M;
      if (N > 1) {
        actualG_inner = (S - 2 * M - N * W) / (N - 1);
      } else {
        actualG_edge = (S - W) / 2;
        actualG_inner = 0;
      }
    }
  }

  if (actualG_edge < 0 || (N > 1 && actualG_inner < 0)) {
    warnings.push('Элементы не помещаются');
  }

  if (!isFirstOffsetFixed && !isMaxEndGapLocked && elementType !== 'calculated' && actualG_edge > M + 0.5) {
    warnings.push(`1-й отступ (${Math.round(actualG_edge)} мм) превышает макс. отступ (${M} мм)`);
  }

  const elementPositions: number[] = [];
  for (let i = 0; i < N; i++) {
    const pos = actualG_edge + i * (W + (N > 1 ? actualG_inner : 0));
    elementPositions.push(pos);
  }

  return {
    edgeToEdge: S,
    centerToCenter: L,
    actualGap: N > 1 ? actualG_inner : actualG_edge,
    elementCount: N,
    firstElementOffset: actualG_edge,
    warnings,
    elementPositions
  };
};

export const formatMm = (val: number): string => {
  return Math.round(val).toString();
};

import { AppConfig } from '../types';

const DIAMETER_MAP: Record<number, number> = { 1200: 0, 1500: 1, 1800: 2 };
const DIAMETER_REVERSE: Record<number, number> = { 0: 1200, 1: 1500, 2: 1800 };

export const serializeConfig = (c: AppConfig): string => {
  const diam = DIAMETER_MAP[c.diameter] ?? 1;
  const dm = c.distanceMode === 'center-to-center' ? 0 : 1;
  const et = c.elementType === 'point' ? 0 : c.elementType === 'board' ? 1 : 2;
  const db = c.distributionMode === 'by-gap' ? 0 : 1;
  const lock = c.isMaxEndGapLocked ? 1 : 0;
  const rm = c.rulerMarkMode === 'edge' ? 0 : 1;
  const fixed = c.isFirstOffsetFixed ? 1 : 0;

  return `v4_${diam}_${dm}_${c.distanceValue}_${et}_${c.boardWidth}_${db}_${c.targetGap}_${c.elementCount}_${c.maxEndGap}_${lock}_${rm}_${fixed}`;
};

export const deserializeConfig = (s: string): Partial<AppConfig> | null => {
  if (!s) return null;

  const getNum = (val: string, fallback: number) => {
    const n = Number(val);
    return isNaN(n) ? fallback : n;
  };

  if (s.startsWith('v4_')) {
    const parts = s.split('_');
    return {
      diameter: DIAMETER_REVERSE[getNum(parts[1], 1)] ?? 1500,
      distanceMode: parts[2] === '0' ? 'center-to-center' : 'edge-to-edge',
      distanceValue: getNum(parts[3], 12000),
      elementType: parts[4] === '0' ? 'point' : parts[4] === '1' ? 'board' : 'calculated',
      boardWidth: getNum(parts[5], 145),
      distributionMode: parts[6] === '0' ? 'by-gap' : 'by-count',
      targetGap: getNum(parts[7], 400),
      elementCount: getNum(parts[8], 5),
      maxEndGap: getNum(parts[9], 300),
      isMaxEndGapLocked: parts[10] === '1',
      rulerMarkMode: parts[11] === '0' ? 'edge' : 'center',
      isFirstOffsetFixed: parts[12] === '1',
    };
  }

  if (s.startsWith('v3_')) {
    const parts = s.split('_');
    return {
      diameter: DIAMETER_REVERSE[getNum(parts[1], 1)] ?? 1500,
      distanceMode: parts[2] === '0' ? 'center-to-center' : 'edge-to-edge',
      distanceValue: getNum(parts[3], 12000),
      elementType: parts[4] === '0' ? 'point' : parts[4] === '1' ? 'board' : 'calculated',
      boardWidth: getNum(parts[5], 145),
      distributionMode: parts[6] === '0' ? 'by-gap' : 'by-count',
      targetGap: getNum(parts[7], 400),
      elementCount: getNum(parts[8], 5),
      maxEndGap: getNum(parts[9], 300),
      isMaxEndGapLocked: parts[10] === '1',
      rulerMarkMode: parts[11] === '0' ? 'edge' : 'center',
      isFirstOffsetFixed: false,
    };
  }

  return null;
};

